INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('kardesim-dogdu', 'Kardeşim Doğdu', 'Benim adım Elif. Dokuz yaşındayım. Dün çok güzel bir gün yaşadım. Kardeşim doğdu!
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Elif''in yeni doğan kardeşinin adı nedir?', 'Ali', 'Can', 'Emre', 'Deniz', 'b', 'Babası bebeği gösterip ''Bu senin kardeşin Can'' diyor.' FROM texts WHERE slug = 'kardesim-dogdu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Can, Elif''in parmağını tutunca Elif ne hissetti?', 'Korktu', 'Kızdı', 'Sıkıldı', 'İçi sevgiyle doldu', 'd', 'Metinde ''İçim sevgiyle doldu'' yazıyor.' FROM texts WHERE slug = 'kardesim-dogdu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Elif, Can için çizdiği resmi nereye astı?', 'Beşiğin yanına', 'Mutfak kapısına', 'Okul panosuna', 'Buzdolabına', 'a', 'Elif resmi Can''ın beşiğinin yanına astı.' FROM texts WHERE slug = 'kardesim-dogdu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu metinden Elif hakkında ne anlıyoruz?', 'Kardeşini kıskanıyor', 'Bebeklerden hoşlanmıyor', 'Ailesine yardım etmeyi seven, sevecen bir abla', 'Hastaneden korkuyor', 'c', 'Elif annesine yardım ediyor, kardeşine ninni söylüyor ve abla olduğu için mutlu.' FROM texts WHERE slug = 'kardesim-dogdu';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('mahalle-pazarinda-alisveris', 'Mahalle Pazarında Alışveriş', 'Her cumartesi mahallemizde pazar kurulur. Bu sabah annemle pazara gittik. Elimizde bir alışveriş listesi vardı. Bez çantalarımızı da unutmadık.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Mahallede pazar hangi gün kuruluyor?', 'Pazartesi', 'Çarşamba', 'Cumartesi', 'Pazar', 'c', 'Metin ''Her cumartesi mahallemizde pazar kurulur'' diye başlıyor.' FROM texts WHERE slug = 'mahalle-pazarinda-alisveris';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Annem domatesleri seçerken hangilerini almadı?', 'Yumuşak olanları', 'Kırmızı olanları', 'Büyük olanları', 'Sert olanları', 'a', 'Annem yumuşak domatesleri almadı.' FROM texts WHERE slug = 'mahalle-pazarinda-alisveris';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Satıcı para üstünü verince çocuk ne yaptı?', 'Cebine koydu', 'Annesine verdi', 'Yere düşürdü', 'Paraları dikkatle saydı', 'd', 'Çocuk paraları dikkatle saydı ve hesabın doğru olduğunu gördü.' FROM texts WHERE slug = 'mahalle-pazarinda-alisveris';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Çocuk bu pazar gezisinden ne kazandı?', 'Yeni bir oyuncak', 'Hem yardım etti hem hesap yapmayı öğrendi', 'Bir arkadaş edindi', 'Satıcı olmaya karar verdi', 'b', 'Son cümlede anneye yardım ettiğini ve hesap yapmayı öğrendiğini söylüyor.' FROM texts WHERE slug = 'mahalle-pazarinda-alisveris';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('kayip-kopek-karamel', 'Kayıp Köpek Karamel', 'Ali ile kız kardeşi Zeynep''in bir köpeği vardı. Köpeğin adı Karamel''di. Karamel kahverengi ve tüylü bir köpekti.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Karamel nasıl kayboldu?', 'Parkta kaçtı', 'Bahçe kapısı açık kaldı', 'Arabadan atladı', 'Okula gitti', 'b', 'Bahçe kapısı açık kalınca Karamel dışarı çıktı.' FROM texts WHERE slug = 'kayip-kopek-karamel';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Karamel''in fırına gittiğini kim söyledi?', 'Fırıncı', 'Anneleri', 'Öğretmen', 'Bakkal amca', 'd', 'Bakkal amca köpeğin fırına doğru koştuğunu söyledi.' FROM texts WHERE slug = 'kayip-kopek-karamel';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ali aramaya giderken yanına ne aldı?', 'Bir düdük', 'Bir top', 'Bir fener', 'Bir tasma', 'a', 'Topu Zeynep aldı, Ali ise düdük aldı.' FROM texts WHERE slug = 'kayip-kopek-karamel';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kardeşler bu olaydan hangi dersi çıkardı?', 'Köpeklerin fırını sevdiğini', 'Parka hiç gitmemek gerektiğini', 'Bahçe kapısını açık bırakmamak gerektiğini', 'Düdüğün gereksiz olduğunu', 'c', 'Eve dönünce kapıyı dikkatle kapattılar ve bir daha açık bırakmamaya karar verdiler.' FROM texts WHERE slug = 'kayip-kopek-karamel';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('yuzmeyi-ogrenen-deniz', 'Yüzmeyi Öğrenen Deniz', 'Deniz sekiz yaşında bir çocuktu. Adı Deniz''di ama suyu hiç sevmezdi. Sudan biraz korkardı.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Deniz başlangıçta sudan neden uzak duruyordu?', 'Sudan biraz korkuyordu', 'Havuz kapalıydı', 'Mayosu yoktu', 'Hastaydı', 'a', 'Metinde Deniz''in sudan biraz korktuğu yazıyor.' FROM texts WHERE slug = 'yuzmeyi-ogrenen-deniz';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Öğretmen Ayşe Hanım ilk gün Deniz''e ne taktı?', 'Gözlük', 'Bone', 'Kolluk', 'Palet', 'c', 'Ayşe Hanım Deniz''e kolluk taktı.' FROM texts WHERE slug = 'yuzmeyi-ogrenen-deniz';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Deniz ikinci hafta ne öğrendi?', 'Suya atlamayı', 'Ayaklarını çırpmayı', 'Sırtüstü yüzmeyi', 'Dalmayı', 'b', 'İkinci hafta ayaklarını çırpmayı öğrendi ve tahtaya tutunarak ilerledi.' FROM texts WHERE slug = 'yuzmeyi-ogrenen-deniz';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu hikâyenin ana fikri nedir?', 'Havuzlar çok derindir', 'Yüzmek sadece yazın yapılır', 'Babalar her zaman alkışlar', 'Sabır ve cesaretle korkular yenilebilir', 'd', 'Deniz vazgeçmeden adım adım ilerleyerek korkusunu yendi.' FROM texts WHERE slug = 'yuzmeyi-ogrenen-deniz';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('bulutlar-ve-yagmur-cesitleri', 'Bulutlar ve Yağmur Çeşitleri', 'Gökyüzüne baktığında pamuk gibi bulutlar görürsün. Peki bulutlar nasıl oluşur, hiç düşündün mü?
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bulutlar neyden oluşur?', 'Dumandan', 'Tozdan', 'Çok küçük su damlacıklarından', 'Pamuktan', 'c', 'Soğuyan buhar küçük damlacıklara dönüşür, milyonlarca damlacık bulutu oluşturur.' FROM texts WHERE slug = 'bulutlar-ve-yagmur-cesitleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Gök gürültülü fırtınaları hangi bulutlar getirir?', 'Kümülonimbüs', 'Sirrüs', 'Stratüs', 'Kümülüs', 'a', 'Büyük ve koyu kümülonimbüs bulutları fırtına getirir.' FROM texts WHERE slug = 'bulutlar-ve-yagmur-cesitleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Fırtına bulutlarında oluşan buz toplarına ne denir?', 'Çisenti', 'Sis', 'Kırağı', 'Dolu', 'd', 'Metinde bu buz toplarına dolu dendiği yazıyor.' FROM texts WHERE slug = 'bulutlar-ve-yagmur-cesitleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre suyun yolculuğu neden ''hiç durmayan bir döngü''dür?', 'Çünkü bulutlar hiç hareket etmez', 'Çünkü yağan su yeniden buharlaşıp tekrar bulut olur', 'Çünkü denizler hiç ısınmaz', 'Çünkü yağmur sadece bir kez yağar', 'b', 'Yağan su denizlere döner, yeniden buharlaşır ve süreç tekrarlanır.' FROM texts WHERE slug = 'bulutlar-ve-yagmur-cesitleri';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('magarada-okul-gezisi', 'Mağarada Bir Okul Gezisi', 'Dördüncü sınıflar o sabah çok heyecanlıydı. Öğretmenleri Murat Bey onları bir mağara gezisine götürüyordu.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Tavandan aşağı doğru sarkan sivri taşlara ne denir?', 'Dikit', 'Sarkıt', 'Sütun', 'Kaya', 'b', 'Selin Hanım tavandan sarkan taşlara sarkıt dendiğini anlattı.' FROM texts WHERE slug = 'magarada-okul-gezisi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Sarkıt ile dikit birleşince oluşan yapının adı nedir?', 'Tünel', 'Kemer', 'Kule', 'Sütun', 'd', 'Selin Hanım ''Buna sütun diyoruz'' dedi.' FROM texts WHERE slug = 'magarada-okul-gezisi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Çocuklar yarasayı görünce neden fısıldadılar?', 'Onu rahatsız etmemek için', 'Korktukları için', 'Öğretmen kızdığı için', 'Yankı yapmasın diye', 'a', 'Metinde yarasayı rahatsız etmemek için fısıldadıkları yazıyor.' FROM texts WHERE slug = 'magarada-okul-gezisi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Defne''nin ''Doğa, çok sabırlı bir sanatçı'' sözüyle ne anlatmak istediği düşünülebilir?', 'Doğanın resim yaptığını', 'Mağaranın çok karanlık olduğunu', 'Mağaradaki güzel şekillerin çok uzun sürede oluştuğunu', 'Yarasaların çok sabırlı olduğunu', 'c', 'Sarkıt, dikit ve sütunlar binlerce yılda oluşur; Defne bu sabrı anlatıyor.' FROM texts WHERE slug = 'magarada-okul-gezisi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('arilarin-bal-yapimi-ve-dansi', 'Arıların Bal Yapımı ve Dansı', 'Kahvaltıda yediğimiz bal, küçük ama çok çalışkan böceklerin emeğidir. Bal arıları bu tatlı yiyeceği nasıl yapar?
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Arıların çiçeklerden topladığı tatlı sıvının adı nedir?', 'Balmumu', 'Polen', 'Şurup', 'Nektar', 'd', 'Çiçeklerin içindeki tatlı sıvıya nektar denir.' FROM texts WHERE slug = 'arilarin-bal-yapimi-ve-dansi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Arılar kanatlarını çırparak nektarı neden yelpazeler?', 'Nektardaki su buharlaşsın diye', 'Kovanı ısıtmak için', 'Ana arıyı uyandırmak için', 'Çiçekleri çağırmak için', 'a', 'Yelpazeleme ile suyun çoğu buharlaşır ve nektar koyulaşarak bala dönüşür.' FROM texts WHERE slug = 'arilarin-bal-yapimi-ve-dansi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Çiçekler uzaktaysa arı nasıl bir dans yapar?', 'Yerinde zıplar', 'Sadece daireler çizer', 'Sekiz rakamına benzeyen bir yol izleyip gövdesini sallar', 'Hiç dans etmez', 'c', 'Uzak çiçekler için sekize benzer bir yol izler ve gövdesini sallar.' FROM texts WHERE slug = 'arilarin-bal-yapimi-ve-dansi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre arıları korumak neden önemlidir?', 'Arılar çok güzel dans ettiği için', 'Hem bal yaptıkları hem de bitkilerin meyve vermesine yardım ettikleri için', 'Kovanlar çok büyük olduğu için', 'Arılar insanlara kitap okuduğu için', 'b', 'Arılar bal üretir ve çiçekten çiçeğe uçarak bitkilerin meyve vermesine yardım eder.' FROM texts WHERE slug = 'arilarin-bal-yapimi-ve-dansi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('miknatislarin-gizemi', 'Mıknatısların Gizemi', 'Buzdolabının kapağına yapışan süsleri hiç merak ettin mi? Onları orada tutan şey mıknatıstır. Mıknatıslar, bazı cisimleri dokunmadan kendine çeken ilginç nesnelerdir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bir mıknatısın uçlarına ne ad verilir?', 'Kutup', 'Kanat', 'İğne', 'Köşe', 'a', 'Mıknatısın iki ucuna kutup denir.' FROM texts WHERE slug = 'miknatislarin-gizemi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'İki mıknatısın aynı kutupları birbirine yaklaşırsa ne olur?', 'Birbirini çeker', 'Isınırlar', 'Birbirini iter', 'Kırılırlar', 'c', 'Aynı kutuplar birbirini iter, farklı kutuplar çeker.' FROM texts WHERE slug = 'miknatislarin-gizemi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Aşağıdakilerden hangisi mıknatısa yapışır?', 'Plastik kaşık', 'Tahta kalem', 'Cam bardak', 'Demir çivi', 'd', 'Demir çiviler mıknatısa yapışır; tahta, plastik ve cam yapışmaz.' FROM texts WHERE slug = 'miknatislarin-gizemi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Pusulanın yön gösterebilmesinin sebebi nedir?', 'İçinde pil olması', 'Dünya''nın dev bir mıknatıs gibi olması', 'Denizcilerin onu çevirmesi', 'Güneş ışığıyla çalışması', 'b', 'Dünya dev bir mıknatıs gibi olduğu için pusulanın mıknatıs iğnesi kuzeyi gösterir.' FROM texts WHERE slug = 'miknatislarin-gizemi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('astronotlar-uzayda-nasil-yasar', 'Astronotlar Uzayda Nasıl Yaşar?', 'Uluslararası Uzay İstasyonu, Dünya''nın çevresinde dönen büyük bir laboratuvardır. Orada astronotlar aylarca yaşar ve çalışır. Peki uzayda günlük hayat nasıldır?
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Astronotlar eşyalarının uçup gitmemesi için ne yapar?', 'Eşyaları dolaba kilitler', 'Cırt cırtlı bantlarla duvarlara tuttururlar', 'Eşyaları ıslatır', 'Hiç eşya kullanmazlar', 'b', 'Eşyalarını cırt cırtlı bantlarla duvarlara tuttururlar.' FROM texts WHERE slug = 'astronotlar-uzayda-nasil-yasar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Astronotlar uzayda ekmek yerine genellikle ne yer?', 'Kraker', 'Simit', 'Pasta', 'Lavaş', 'd', 'Ekmek kırıntıları uçuştuğu için lavaş tercih edilir.' FROM texts WHERE slug = 'astronotlar-uzayda-nasil-yasar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Astronotlar her gün neden yaklaşık iki saat spor yapar?', 'Kasları ve kemikleri zayıflamasın diye', 'Canları sıkıldığı için', 'Yarışmaya hazırlandıkları için', 'İstasyonu hareket ettirmek için', 'a', 'Uzayda kaslar ve kemikler az çalıştığı için zayıflayabilir.' FROM texts WHERE slug = 'astronotlar-uzayda-nasil-yasar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Astronotların uyurken göz bandı takmalarının sebebi nedir?', 'Gözleri ağrıdığı için', 'İstasyonda lamba olmadığı için', 'Bir günde birçok kez güneş doğup battığı için', 'Uzay çok soğuk olduğu için', 'c', 'İstasyon çok hızlı döndüğü için bir günde on altı kez güneş doğar; ışık uykuyu bölebilir.' FROM texts WHERE slug = 'astronotlar-uzayda-nasil-yasar';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('yunuslarin-iletisimi', 'Yunusların İletişimi', 'Yunuslar denizlerin en zeki ve en sosyal canlıları arasında yer alır. Genellikle gruplar halinde yaşarlar. Bu gruplarda avlanmak, yavrulara bakmak ve tehlikelerden korunmak için sürekli haberleşirler. Peki yunuslar birbirleriyle nasıl konuşur?
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Her yunusun kendine özgü ıslığı neye benzetilmiştir?', 'Bir şarkıya', 'Bir isme', 'Bir haritaya', 'Bir oyuna', 'b', 'Metinde bu ıslığın bir çeşit isim gibi olduğu söyleniyor.' FROM texts WHERE slug = 'yunuslarin-iletisimi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yunusların ekolokasyon yeteneği ne işe yarar?', 'Daha hızlı yüzmeye', 'Suyun sıcaklığını ölçmeye', 'Yankıyı dinleyerek nesnelerin yerini ve büyüklüğünü anlamaya', 'Uzun süre uyumaya', 'c', 'Tıklama sesleri nesnelere çarpıp geri döner; yunus yankıyı dinleyerek nesneyi tanır.' FROM texts WHERE slug = 'yunuslarin-iletisimi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kuyrukla suya sert vurmak bazen ne anlama gelir?', 'Uyarı', 'Selamlaşma', 'Uyku zamanı', 'Oyun daveti', 'a', 'Metinde bunun bazen bir uyarı anlamına geldiği yazıyor.' FROM texts WHERE slug = 'yunuslarin-iletisimi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre gürültülü denizler yunuslar için neden sorun olabilir?', 'Yunuslar gürültüden hoşlandığı için', 'Suyu ısıttığı için', 'Balıkları çoğalttığı için', 'Yunusların birbirini duymasını zorlaştırdığı için', 'd', 'Yunuslar sesle haberleştiği için gürültü birbirlerini duymalarını zorlaştırır.' FROM texts WHERE slug = 'yunuslarin-iletisimi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('ses-nasil-yayilir', 'Ses Nasıl Yayılır?', 'Bir arkadaşın sana seslendiğinde onun sesini nasıl duyarsın? Sesin ağızdan kulağa ulaşması aslında şaşırtıcı bir yolculuktur.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ses nasıl oluşur?', 'Işıkla', 'Titreşimlerle', 'Rüzgârla', 'Elektrikle', 'b', 'Metin ''Ses, titreşimlerle oluşur'' diyor.' FROM texts WHERE slug = 'ses-nasil-yayilir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Uzayda neden ses duyulmaz?', 'Uzay çok soğuk olduğu için', 'Yıldızlar sesi yuttuğu için', 'Uzayda sesi taşıyacak hava olmadığı için', 'Astronotların kulakları kapalı olduğu için', 'c', 'Sesin yayılması için bir ortam gerekir, uzayda hava yoktur.' FROM texts WHERE slug = 'ses-nasil-yayilir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Fırtınada şimşeği gök gürültüsünden önce görmemizin sebebi nedir?', 'Işığın sesten çok daha hızlı olması', 'Şimşeğin daha önce oluşması', 'Gözlerimizin kulaklarımızdan iyi olması', 'Gök gürültüsünün bulutlarda beklemesi', 'a', 'Ses hızlıdır ama ışık kadar hızlı değildir.' FROM texts WHERE slug = 'ses-nasil-yayilir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ses aşağıdakilerin hangisinde havadakinden yaklaşık dört kat daha hızlı yayılır?', 'Uzayda', 'Sisli havada', 'Boşlukta', 'Suda', 'd', 'Metinde ses suda havadakinden yaklaşık dört kat hızlı yayıldığı yazıyor.' FROM texts WHERE slug = 'ses-nasil-yayilir';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('volkanlar-ates-dagi', 'Volkanlar', 'Dünyamızın içi, sandığımızdan çok daha sıcaktır. Yerin derinliklerinde kayalar o kadar ısınır ki eriyerek magma denen koyu ve akışkan bir maddeye dönüşür. Magma, çevresindeki kayalardan daha hafif olduğu için yavaş yavaş yukarı doğru yükselir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yeryüzüne ulaşan magmaya ne ad verilir?', 'Kül', 'Tüf', 'Lav', 'Buhar', 'c', 'Metinde yeryüzüne ulaşan magmaya lav dendiği yazıyor.' FROM texts WHERE slug = 'volkanlar-ates-dagi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Sık sık püsküren volkanlara ne denir?', 'Etkin volkan', 'Sönmüş volkan', 'Uyuyan dağ', 'Buzul', 'a', 'Sık sık püsküren volkanlara etkin volkan denir.' FROM texts WHERE slug = 'volkanlar-ates-dagi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Aşağıdakilerden hangisi metinde adı geçen volkanik dağlardan biri değildir?', 'Ağrı Dağı', 'Erciyes Dağı', 'Nemrut Dağı', 'Uludağ', 'd', 'Metinde Ağrı, Erciyes ve Nemrut dağları sayılıyor; Uludağ geçmiyor.' FROM texts WHERE slug = 'volkanlar-ates-dagi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre volkanların doğaya faydası nedir?', 'Havayı soğutmaları', 'Küllerinin toprağı zenginleştirmesi', 'Denizleri tatlandırmaları', 'Yağmuru durdurmaları', 'b', 'Volkanik kül toprağı zenginleştirir ve bitkiler iyi yetişir.' FROM texts WHERE slug = 'volkanlar-ates-dagi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('telefonun-kisa-tarihi', 'Telefonun Kısa Tarihi', 'Bugün cebimizdeki telefonla dünyanın öbür ucundaki biriyle görüntülü konuşabiliyoruz. Oysa yaklaşık 150 yıl önce uzaktaki birine haber ulaştırmak günler, hatta haftalar sürebiliyordu.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Alexander Graham Bell telefonun patentini hangi yıl aldı?', '1776', '1876', '1973', '2007', 'b', 'Metinde 1876 yılı geçiyor.' FROM texts WHERE slug = 'telefonun-kisa-tarihi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'İlk zamanlarda telefon görüşmelerini kim bağlıyordu?', 'Santraldeki bir görevli', 'Postacı', 'Bilgisayar', 'Arayan kişinin kendisi', 'a', 'Santraldeki görevli kabloları elle takarak iki kişiyi bağlardı.' FROM texts WHERE slug = 'telefonun-kisa-tarihi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'İlk cep telefonları neye benzetilmiştir?', 'Bir kaleme', 'Bir saate', 'Bir kitaba', 'Bir tuğlaya', 'd', 'İlk cep telefonları bir tuğla kadar büyük ve ağırdı.' FROM texts WHERE slug = 'telefonun-kisa-tarihi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metnin ana fikri aşağıdakilerden hangisidir?', 'Telefonlar hiç değişmemiştir', 'Çevirmeli telefonlar en iyisidir', 'Telefon, zaman içinde küçük adımlarla büyük bir değişim geçirmiştir', 'Akıllı telefonlar sadece oyun içindir', 'c', 'Metin telefonun tellerden akıllı telefonlara uzanan değişimini anlatıyor.' FROM texts WHERE slug = 'telefonun-kisa-tarihi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('satranc-bir-spor-mu', 'Satranç Bir Spor mu?', 'Spor denince çoğumuzun aklına futbol, basketbol ya da koşu gelir. Peki masa başında oturarak oynanan satranç da bir spor sayılabilir mi?
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Satranç tahtasında kaç kare vardır?', '16', '32', '48', '64', 'd', 'Satranç 64 kareli bir tahta üzerinde oynanır.' FROM texts WHERE slug = 'satranc-bir-spor-mu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Rakibin şahı kaçamayacak duruma gelince buna ne denir?', 'Rok', 'Şah mat', 'Pat', 'Terfi', 'b', 'Metinde bu duruma şah mat dendiği yazıyor.' FROM texts WHERE slug = 'satranc-bir-spor-mu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Usta satranççılar neden düzenli egzersiz yapar?', 'Uzun oyunlarda dikkat toplamak insanı çok yorduğu için', 'Satranç taşları çok ağır olduğu için', 'Kurallar bunu zorunlu tuttuğu için', 'Turnuvalar koşarak oynandığı için', 'a', 'Saatlerce süren oyunlarda dikkatini toplamak çok yorucudur.' FROM texts WHERE slug = 'satranc-bir-spor-mu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yazarın satranç hakkındaki görüşü nedir?', 'Satranç sadece bir masa oyunudur', 'Satranç çocuklar için uygun değildir', 'Satranç, zihni çalıştıran gerçek bir spordur', 'Satranç futboldan daha zordur', 'c', 'Son cümlede satrancın zihni çalıştıran gerçek bir spor olduğu söyleniyor.' FROM texts WHERE slug = 'satranc-bir-spor-mu';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('marstaki-gezgin-robotlar', 'Mars''taki Gezgin Robotlar', 'Mars, Güneş''e uzaklık bakımından dördüncü gezegendir. Toprağındaki demir oksit nedeniyle kırmızı görünür, bu yüzden ona Kızıl Gezegen de denir. Mars''a henüz hiçbir insan ayak basmadı. Ancak orada yıllardır çalışan tekerlekli robotlar var. Bu robotlara gezgin ya da keşif aracı denir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Mars''a neden Kızıl Gezegen denir?', 'Çok sıcak olduğu için', 'Toprağındaki demir oksit onu kırmızı gösterdiği için', 'Güneş''e en yakın gezegen olduğu için', 'Üzerinde kırmızı bitkiler olduğu için', 'b', 'Demir oksit nedeniyle Mars kırmızı görünür.' FROM texts WHERE slug = 'marstaki-gezgin-robotlar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Mars''a ulaşan ilk gezginin adı nedir?', 'Curiosity', 'Opportunity', 'Perseverance', 'Sojourner', 'd', 'İlk gezgin Sojourner 1997''de Mars''a ulaştı.' FROM texts WHERE slug = 'marstaki-gezgin-robotlar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ingenuity''yi özel yapan nedir?', 'Başka bir gezegende uçan ilk araç olması', 'En büyük gezgin olması', 'Mars''a ilk inen araç olması', 'İçinde astronot taşıması', 'a', 'Ingenuity başka bir gezegende uçan ilk araç oldu.' FROM texts WHERE slug = 'marstaki-gezgin-robotlar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Gezginlerin bazı kararları kendi başına verebilmesi neden gereklidir?', 'Bilim insanları uyuduğu için', 'Mars''ta internet çok hızlı olduğu için', 'Mesajların Dünya''dan Mars''a ulaşması dakikalar sürdüğü için', 'Gezginler çok küçük olduğu için', 'c', 'Mesajlar gecikmeli ulaştığı için anlık kumanda mümkün değildir.' FROM texts WHERE slug = 'marstaki-gezgin-robotlar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Gezginler sayesinde Mars hakkında ne öğrenildi?', 'Mars''ta bugün ormanlar olduğu', 'Mars''ta geçmişte nehirler ve göller bulunduğu', 'Mars''ta insanların yaşadığı', 'Mars''ın Güneş''e en yakın gezegen olduğu', 'b', 'Bilim insanları Mars''ta çok eskiden nehirlerin ve göllerin bulunduğunu öğrendi.' FROM texts WHERE slug = 'marstaki-gezgin-robotlar';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('uc-boyutlu-yazicilar', '3B Yazıcılar', 'Evdeki yazıcılar kâğıda yazı ve resim basar. Peki bir yazıcının oyuncak, bardak ya da makine parçası basabildiğini düşünebiliyor musun? Üç boyutlu yazıcılar, yani 3B yazıcılar, tam olarak bunu yapar.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, '3B yazıcıyla bir nesne basmadan önce ilk olarak ne yapılır?', 'Plastik ip kesilir', 'Nesnenin bilgisayarda dijital modeli çizilir', 'Tabla ısıtılır', 'Nesnenin fotoğrafı çekilir', 'b', 'Her şey bilgisayarda nesnenin dijital modelinin çizilmesiyle başlar.' FROM texts WHERE slug = 'uc-boyutlu-yazicilar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metinde yazıcının erimiş plastiği bırakması neye benzetilmiştir?', 'Kalemle yazı yazmaya', 'Resim boyamaya', 'Krema sıkmaya', 'Kum dökmeye', 'c', 'Isınan uç, plastiği krema sıkar gibi ince bir çizgi halinde bırakır.' FROM texts WHERE slug = 'uc-boyutlu-yazicilar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, '3B yazıcılar nesneleri nasıl oluşturur?', 'Katman katman üst üste ekleyerek', 'Büyük bir bloğu keserek', 'Kalıba sıvı dökerek', 'Parçaları yapıştırarak', 'a', 'İşlem katman katman tekrarlanır ve nesne yavaş yavaş yükselir.' FROM texts WHERE slug = 'uc-boyutlu-yazicilar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Doktorlar 3B yazıcıları ne için kullanır?', 'İlaç yapmak için', 'Hastane yatağı basmak için', 'Aşı üretmek için', 'Hastalara uygun protezler hazırlamak için', 'd', 'Doktorlar hastalara tam uyan yapay el ve bacaklar hazırlar.' FROM texts WHERE slug = 'uc-boyutlu-yazicilar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yazara göre bu teknolojinin en güzel yanı nedir?', 'Çok ucuz olması', 'Sessiz çalışması', 'Fikirlerin kısa sürede gerçeğe dönüşebilmesi', 'Sadece plastik kullanması', 'c', 'Son paragrafta en güzel yanın fikirleri hızla gerçeğe dönüştürmek olduğu söyleniyor.' FROM texts WHERE slug = 'uc-boyutlu-yazicilar';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('truva-ve-tahta-at-efsanesi', 'Truva ve Tahta At Efsanesi', 'Çanakkale''de, Hisarlık adı verilen bir tepede çok eski bir şehrin kalıntıları bulunur. Burası Truva Antik Kenti''dir. Arkeologlar bu tepede, binlerce yıl boyunca birbirinin üzerine kurulmuş pek çok şehir katmanı ortaya çıkarmıştır. Kalıntıların en eskileri yaklaşık beş bin yıl öncesine uzanır. İlk büyük kazıları 1870''li yıllarda Heinrich Schliemann başlatmış, daha sonra pek çok bilim insanı çalışmaları sürdürmüştür. Truva, 1998 yılında UNESCO Dünya Mirası Listesi''ne alınmıştır.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Truva Antik Kenti hangi ilimizdedir?', 'İzmir', 'Çanakkale', 'Antalya', 'Bursa', 'b', 'Truva, Çanakkale''deki Hisarlık tepesindedir.' FROM texts WHERE slug = 'truva-ve-tahta-at-efsanesi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Efsaneye göre Yunan askerleri şehre nasıl girdi?', 'Surları yıkarak', 'Tünel kazarak', 'Dev bir tahta atın içine saklanarak', 'Gemilerle nehirden geçerek', 'c', 'Askerler tahta atın içine saklandı ve gece dışarı çıkıp kapıları açtı.' FROM texts WHERE slug = 'truva-ve-tahta-at-efsanesi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Tahta at hikâyesi hakkında hangisi doğrudur?', 'Tarihçiler bunu bir efsane olarak kabul eder', 'Kazılarda gerçek tahta at bulunmuştur', 'Hikâye geçen yüzyılda uydurulmuştur', 'At hâlâ Truva''da saklanmaktadır', 'a', 'Metinde tarihçilerin tahta at hikâyesini efsane olarak kabul ettiği belirtiliyor.' FROM texts WHERE slug = 'truva-ve-tahta-at-efsanesi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kazılar Truva hakkında neyi göstermiştir?', 'Şehrin hiç var olmadığını', 'Şehrin sadece bir kez kurulduğunu', 'Şehrin denizin altında olduğunu', 'Gerçek bir şehir olduğunu ve birkaç kez yıkılıp yeniden kurulduğunu', 'd', 'Kazılarda üst üste kurulmuş şehir katmanları bulunmuştur.' FROM texts WHERE slug = 'truva-ve-tahta-at-efsanesi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Truvalıların hatası neydi?', 'Surlarını çok yüksek yapmaları', 'Görünüşe aldanıp atı sorgulamadan şehre almaları', 'Savaşa hiç katılmamaları', 'Gemileri yakmaları', 'b', 'Savaşın bittiğini sanıp atı şehre soktular; bu yüzden efsane görünene hemen inanmamayı hatırlatır.' FROM texts WHERE slug = 'truva-ve-tahta-at-efsanesi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('kapadokya-ve-peri-bacalari', 'Kapadokya ve Peri Bacaları', 'Nevşehir ve çevresini kapsayan Kapadokya bölgesi, dünyanın en ilginç manzaralarından birine sahiptir. Burada şapka takmış gibi görünen sivri kaya kuleleri yükselir. Bu kayalara peri bacası denir. Peki bu tuhaf şekiller nasıl oluştu?
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Volkanik kül tabakaları sıkışınca hangi kaya oluştu?', 'Mermer', 'Granit', 'Tüf', 'Kireç taşı', 'c', 'Kül tabakaları sıkışarak tüf adı verilen yumuşak kayaya dönüştü.' FROM texts WHERE slug = 'kapadokya-ve-peri-bacalari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Peri bacalarının tepesindeki ''şapka'' neden oluşmuştur?', 'Sert kaya parçalarının altındaki kısımlar daha az aşındığı için', 'İnsanlar taşları üst üste koyduğu için', 'Kar yağışı donduğu için', 'Kuşlar yuva yaptığı için', 'a', 'Sert kaya, altındaki yumuşak tüfü aşınmaya karşı korudu.' FROM texts WHERE slug = 'kapadokya-ve-peri-bacalari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metinde adı geçen yeraltı şehirleri hangileridir?', 'Göreme ve Ürgüp', 'Efes ve Bergama', 'Hasan ve Göllü', 'Derinkuyu ve Kaymaklı', 'd', 'Derinkuyu ve Kaymaklı yeraltı şehirleri olarak anılıyor.' FROM texts WHERE slug = 'kapadokya-ve-peri-bacalari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'İnsanların Kapadokya''da kayaları oyarak ev yapabilmesinin sebebi nedir?', 'Bölgede hiç ağaç olmaması', 'Tüfün kolay oyulabilen bir kaya olması', 'Kayaların içinin boş olması', 'Volkanların hâlâ etkin olması', 'b', 'Tüf yumuşak ve kolay oyulabilen bir kayadır.' FROM texts WHERE slug = 'kapadokya-ve-peri-bacalari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metnin ana fikri aşağıdakilerden hangisidir?', 'Kapadokya sadece balonlarıyla ünlüdür', 'Volkanlar tehlikeli olduğu için uzak durmalıyız', 'Kapadokya, doğanın ve insan emeğinin birlikte şekillendirdiği korunması gereken eşsiz bir yerdir', 'Peri bacaları insanlar tarafından yapılmıştır', 'c', 'Metin hem doğal oluşumu hem de insan yapılarını anlatıp korunma çağrısıyla bitiyor.' FROM texts WHERE slug = 'kapadokya-ve-peri-bacalari';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('gobeklitepe-tarihin-sifir-noktasi', 'Göbeklitepe', 'Şanlıurfa''nın yakınlarındaki bir tepede, insanlık tarihine bakışımızı değiştiren bir keşif yapıldı. Burası Göbeklitepe''dir. Araştırmalar, buradaki yapıların yaklaşık on iki bin yıl önce inşa edilmeye başlandığını gösteriyor. Bu da onların Mısır piramitlerinden yedi bin yıldan daha eski olduğu anlamına gelir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Göbeklitepe''deki yapılar yaklaşık kaç yıl önce inşa edilmeye başlanmıştır?', 'Bin yıl önce', 'Dört bin yıl önce', 'On iki bin yıl önce', 'Yüz bin yıl önce', 'c', 'Araştırmalar yapıların yaklaşık on iki bin yıl önce inşa edilmeye başlandığını gösteriyor.' FROM texts WHERE slug = 'gobeklitepe-tarihin-sifir-noktasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Göbeklitepe''deki dikilitaşlar hangi harfe benzer?', 'T', 'L', 'O', 'Y', 'a', 'Dikilitaşlar T harfine benzer.' FROM texts WHERE slug = 'gobeklitepe-tarihin-sifir-noktasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Göbeklitepe''yi yapan insanlar nasıl yaşıyordu?', 'Büyük şehirlerde ticaret yaparak', 'Buğday ekip hasat ederek', 'Hayvan sürüleri besleyerek', 'Avlanarak ve yabani bitkiler toplayarak', 'd', 'Onlar avcı-toplayıcıydı, henüz tarım yapmıyorlardı.' FROM texts WHERE slug = 'gobeklitepe-tarihin-sifir-noktasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Göbeklitepe, bilim insanlarının hangi eski düşüncesini sorgulatmıştır?', 'İnsanların hayvan resmi yapamayacağını', 'Büyük yapıların ancak tarıma geçildikten sonra yapılabileceğini', 'Taş aletlerin hiç kullanılmadığını', 'Mısır piramitlerinin en yeni yapılar olduğunu', 'b', 'Avcı-toplayıcıların bu yapıları inşa etmesi, tarımdan önce büyük yapılar yapılamayacağı görüşünü sorgulattı.' FROM texts WHERE slug = 'gobeklitepe-tarihin-sifir-noktasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Taşların metal alet olmadan yontulup taşınması o dönemin insanları hakkında ne gösterir?', 'Çok örgütlü olduklarını ve iş birliği yaptıklarını', 'Tek başlarına yaşadıklarını', 'Taşlara ilgi duymadıklarını', 'Metal aletleri sakladıklarını', 'a', 'Metin bu işin büyük iş birliği gerektirdiğini ve insanların sanıldığından örgütlü olduğunu söylüyor.' FROM texts WHERE slug = 'gobeklitepe-tarihin-sifir-noktasi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('amazon-yagmur-ormanlari', 'Amazon Yağmur Ormanları', 'Güney Amerika''nın büyük bir bölümünü kaplayan Amazon, dünyanın en büyük tropikal yağmur ormanıdır. Bu dev orman dokuz ülkenin topraklarına yayılır, ancak en büyük kısmı Brezilya''dadır. Ormanın içinden, taşıdığı su miktarı bakımından dünyanın en büyük nehri olan Amazon Nehri akar.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Amazon yağmur ormanlarının en büyük kısmı hangi ülkededir?', 'Brezilya', 'Meksika', 'Arjantin', 'Şili', 'a', 'Orman dokuz ülkeye yayılır, en büyük kısmı Brezilya''dadır.' FROM texts WHERE slug = 'amazon-yagmur-ormanlari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ağaçların yapraklarından oluşan ve gökyüzünü kapatan kalın örtüye ne denir?', 'Orman zemini', 'Orman tacı', 'Nehir yatağı', 'Sis perdesi', 'b', 'Metinde bu örtüye orman tacı dendiği yazıyor.' FROM texts WHERE slug = 'amazon-yagmur-ormanlari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ormanın zemini gündüz bile neden loştur?', 'Sürekli sis olduğu için', 'Güneş hiç doğmadığı için', 'Hayvanlar ışığı engellediği için', 'Güneş ışığının büyük bölümü orman tacında kaldığı için', 'd', 'Kalın yaprak örtüsü güneş ışığının çoğunu tutar.' FROM texts WHERE slug = 'amazon-yagmur-ormanlari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Aşağıdakilerden hangisi metinde Amazon''da yaşadığı söylenen canlılardan biri değildir?', 'Jaguar', 'Tembel hayvan', 'Kutup ayısı', 'Pembe nehir yunusu', 'c', 'Kutup ayısı soğuk bölgelerde yaşar; metinde geçmez.' FROM texts WHERE slug = 'amazon-yagmur-ormanlari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre Amazon''u korumak neden bütün dünya için önemlidir?', 'Sadece turistler için güzel bir yer olduğu için', 'Karbondioksiti tutup oksijen ürettiği ve iklimi dengelemeye yardım ettiği için', 'Dünyanın en soğuk yeri olduğu için', 'Orada hiç insan yaşamadığı için', 'b', 'Amazon''un etkisi kendi bölgesiyle sınırlı değildir; iklimi ve havayı etkiler.' FROM texts WHERE slug = 'amazon-yagmur-ormanlari';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('penguenler-yuzen-kuslar', 'Penguenler: Yüzen Kuşlar', 'Penguenler çok sevimli kuşlardır. Onların da tüyleri ve gagaları vardır. Ama penguenler uçamaz. Kanatları küçük ve serttir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Penguenler kanatlarını ne için kullanır?', 'Uçmak için', 'Su altında yüzmek için', 'Yuva yapmak için', 'Yiyecek taşımak için', 'b', 'Metinde penguenlerin kanatlarını su altında kürek gibi kullandığı yazıyor.' FROM texts WHERE slug = 'penguenler-yuzen-kuslar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Penguenler soğuk suda neden üşümez?', 'Sürekli hareket ettikleri için', 'Suya hiç girmedikleri için', 'Tüyleri sık ve yağlı, derilerinin altında yağ tabakası olduğu için', 'Sıcak yiyecekler yedikleri için', 'c', 'Sık ve yağlı tüyler ile kalın yağ tabakası penguenleri soğuktan korur.' FROM texts WHERE slug = 'penguenler-yuzen-kuslar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'İmparator penguenlerinde yumurtayı ayaklarının üstünde kim taşır?', 'Anne penguen', 'Yavru penguen', 'Başka bir kuş', 'Baba penguen', 'd', 'Anne denize gidince yumurtayı baba penguen ayaklarının üstünde taşır.' FROM texts WHERE slug = 'penguenler-yuzen-kuslar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre aşağıdakilerden hangisi doğrudur?', 'Her penguen karlı ve buzlu yerlerde yaşamaz.', 'Penguenler çok yükseğe uçabilir.', 'Penguenler yalnızca bitki yer.', 'Penguenler dünyanın kuzeyinde yaşar.', 'a', 'Metinde bazı penguenlerin ılık kıyılarda yaşadığı, yani her penguenin karda yaşamadığı anlatılıyor.' FROM texts WHERE slug = 'penguenler-yuzen-kuslar';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('dislerimizi-neden-fircalariz', 'Dişlerimizi Neden Fırçalarız?', 'Sabah oldu. Ela yüzünü yıkadı. Sonra diş fırçasını aldı. Annesi ona gülümsedi.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ağızdaki bakteriler neyle beslenir?', 'Şekerli yiyeceklerle', 'Sadece sudan', 'Diş macunuyla', 'Havayla', 'a', 'Annesi bakterilerin şekerli şeylerle beslendiğini anlatıyor.' FROM texts WHERE slug = 'dislerimizi-neden-fircalariz';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Dişler günde kaç kez fırçalanmalıdır?', 'Bir kez', 'Hiç', 'İki kez', 'Beş kez', 'c', 'Metinde dişlerin sabah ve gece olmak üzere günde iki kez fırçalanması gerektiği yazıyor.' FROM texts WHERE slug = 'dislerimizi-neden-fircalariz';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Her fırçalama yaklaşık ne kadar sürmelidir?', 'On saniye', 'İki dakika', 'Yarım saat', 'Bir saat', 'b', 'Annesi her fırçalamanın yaklaşık iki dakika sürmesi gerektiğini söylüyor.' FROM texts WHERE slug = 'dislerimizi-neden-fircalariz';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu metin en çok ne anlatıyor?', 'Ela''nın okula nasıl gittiğini', 'Diş macununun nasıl yapıldığını', 'Annenin kahvaltı hazırlamasını', 'Dişleri fırçalamanın çürükleri önlediğini', 'd', 'Metnin ana fikri, fırçalamanın bakterileri azaltarak dişleri çürükten korumasıdır.' FROM texts WHERE slug = 'dislerimizi-neden-fircalariz';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('bayram-ziyareti', 'Bayram Ziyareti', 'Bugün bayramın ilk günü. Mert erkenden uyandı. Yeni gömleğini giydi. Kardeşi Zeynep de kırmızı elbisesini giydi.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Aile bayramın ilk günü önce kimi ziyaret etti?', 'Öğretmeni', 'Dedeyle nineyi', 'Hatice Teyze''yi', 'Teyzesini', 'b', 'Metinde ailenin önce dedeyle nineyi ziyaret ettiği yazıyor.' FROM texts WHERE slug = 'bayram-ziyareti';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ninesi Mert''e ne hediye etti?', 'Bir top', 'Bir bebek', 'Bir kitap', 'Bir mendil', 'd', 'Ninesi Mert''e bir mendil, Zeynep''e bir bebek verdi.' FROM texts WHERE slug = 'bayram-ziyareti';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Can kimdir?', 'Hatice Teyze''nin torunu', 'Mert''in ağabeyi', 'Mert''in öğretmeni', 'Zeynep''in sınıf arkadaşı', 'a', 'Hatice Teyze yanında torunu Can ile gelmişti.' FROM texts WHERE slug = 'bayram-ziyareti';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Mert''e göre en güzel hediye neydi?', 'Yeni gömleği', 'Masadaki lokumlar', 'Sevdikleriyle geçirdiği zaman', 'Bahçedeki top', 'c', 'Metnin sonunda Mert en güzel hediyenin sevdikleriyle geçirdiği zaman olduğunu düşünüyor.' FROM texts WHERE slug = 'bayram-ziyareti';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('basketbolun-icadi', 'Basketbol Nasıl İcat Edildi?', 'Basketbol çok sevilen bir spordur. Peki bu oyunu kim buldu? Hikâyesi yüz yıldan daha eskidir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Basketbolu kim icat etti?', 'Bir futbolcu', 'Bir doktor', 'James Naismith adında bir öğretmen', 'Bir okul müdürü', 'c', 'Metinde oyunu öğretmen James Naismith''in bulduğu yazıyor.' FROM texts WHERE slug = 'basketbolun-icadi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Naismith neden yeni bir oyun düşündü?', 'Hava soğuk olduğu için öğrenciler dışarıda oynayamıyordu.', 'Öğrenciler futboldan hiç hoşlanmıyordu.', 'Okulda hiç top yoktu.', 'Bir yarışma kazanmak istiyordu.', 'a', 'Kış olduğu için öğrenciler dışarıda oynayamıyor ve salonda sıkılıyordu.' FROM texts WHERE slug = 'basketbolun-icadi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'İlk basketbol oyununda pota yerine ne kullanıldı?', 'Kova', 'Çember', 'Kutu', 'Şeftali sepeti', 'd', 'Naismith salonun iki ucuna şeftali sepetleri astı.' FROM texts WHERE slug = 'basketbolun-icadi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'İlk oyunlarda birinin merdivene çıkması neden gerekiyordu?', 'Salonun ışıklarını açmak için', 'Sepetin altı kapalı olduğu için topu almak gerekiyordu', 'Sepetleri boyamak için', 'Oyuncuları izlemek için', 'b', 'Sepetin altı kapalı olduğundan top içeride kalıyordu; biri merdivenle çıkıp alıyordu.' FROM texts WHERE slug = 'basketbolun-icadi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('caretta-caretta-kaplumbagalari', 'Caretta Caretta Deniz Kaplumbağaları', 'Caretta caretta, denizlerde yaşayan büyük bir kaplumbağa türüdür. Türkçede iribaş deniz kaplumbağası olarak da bilinir. Sırtındaki kabuk kahverengi ve kırmızımsıdır. Yetişkin bir caretta, bir metreye yakın uzunlukta olabilir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Dişi caretta kaplumbağaları neden karaya çıkar?', 'Güneşlenmek için', 'Yumurtlamak için', 'Yiyecek bulmak için', 'Uyumak için', 'b', 'Metinde dişilerin yumurtlamak için karaya çıktığı yazıyor.' FROM texts WHERE slug = 'caretta-caretta-kaplumbagalari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yavruların dişi ya da erkek olmasını ne etkiler?', 'Annenin büyüklüğü', 'Denizin rengi', 'Kumun sıcaklığı', 'Yumurtanın şekli', 'c', 'Sıcak kumda daha çok dişi, serin kumda daha çok erkek yavru çıkar.' FROM texts WHERE slug = 'caretta-caretta-kaplumbagalari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yavrular yumurtadan çıkınca neye doğru yürür?', 'Ay ışığının denizdeki parıltısına', 'Kumsaldaki ağaçlara', 'Annelerinin sesine', 'En yakın kayalara', 'a', 'Yavrular ay ışığının denizdeki parıltısına doğru yürür.' FROM texts WHERE slug = 'caretta-caretta-kaplumbagalari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yuvalama kumsallarında gece ışık yakılmaması neden önemlidir?', 'Kumsal daha güzel göründüğü için', 'Elektrik pahalı olduğu için', 'Balıklar ışıktan korktuğu için', 'Parlak ışıklar yavruların denizi bulmasını zorlaştırdığı için', 'd', 'Yavrular ay ışığını izleyerek denize gider; parlak ışıklar onların yolunu şaşırtır.' FROM texts WHERE slug = 'caretta-caretta-kaplumbagalari';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('buz-neden-suda-yuzer', 'Buz Neden Suda Yüzer?', 'Bir bardak suya buz koyduğunda ne olur? Buz dibe batmaz, suyun üstünde yüzer. Oysa buz da sudan yapılmıştır. Peki neden batmaz?
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Su donup buza dönüşürken ne olur?', 'Genleşir ve daha çok yer kaplar.', 'Büzülür ve küçülür.', 'Rengi değişir.', 'Tamamen kaybolur.', 'a', 'Metinde suyun donarken genleştiği, yani daha çok yer kapladığı anlatılıyor.' FROM texts WHERE slug = 'buz-neden-suda-yuzer';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Buzun içinde boşluklar olmasının sebebi nedir?', 'Buza hava pompalanması', 'Suyun içindeki kum', 'Buzun çok hızlı erimesi', 'Parçacıkların donarken düzenli dizilmesi', 'd', 'Su donunca parçacıklar düzenli dizilir ve aralarında boşluklar kalır.' FROM texts WHERE slug = 'buz-neden-suda-yuzer';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ağzına kadar dolu kap dondurucuya konursa ertesi gün ne görülür?', 'Suyun azaldığı', 'Buzun kabın ağzından taştığı', 'Kabın boşaldığı', 'Suyun hiç donmadığı', 'b', 'Su donarken genleştiği için buz kabın ağzından taşar.' FROM texts WHERE slug = 'buz-neden-suda-yuzer';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Buzun yüzmesi göllerde yaşayan canlılar için neden önemlidir?', 'Balıkların buzun üstünde yürümesini sağlar.', 'Gölün suyunu ısıtıp kaynatır.', 'Buz üstte kalıp alttaki suyu korur, canlılar yaşamaya devam eder.', 'Göldeki bütün suyu dondurur.', 'c', 'Buz tabakası bir örtü gibi alttaki suyu korur ve canlılar orada yaşar.' FROM texts WHERE slug = 'buz-neden-suda-yuzer';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('bir-adada-kamp', 'Bir Adada Kamp', 'Deniz ve kuzeni Arda, yaz tatilinde aileleriyle birlikte küçük bir adaya gittiler. Adaya bir tekneyle yarım saatte ulaştılar. Burada ne ev ne de market vardı. Sadece çam ağaçları, kayalar ve masmavi bir deniz vardı.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Babasına göre çadır nereye kurulmalıydı?', 'Denizin hemen kenarına', 'En yüksek kayanın üstüne', 'Rüzgârın az estiği düz bir yere', 'Ağaçların dallarına', 'c', 'Babası çadırın rüzgârın az estiği düz bir yere kurulması gerektiğini söyledi.' FROM texts WHERE slug = 'bir-adada-kamp';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Deniz kıyıda ne buldu?', 'Bir martı tüyü', 'Bir deniz kabuğu', 'Bir şişe', 'Bir yengeç', 'a', 'Deniz bir martı tüyü buldu ve defterine yapıştırdı.' FROM texts WHERE slug = 'bir-adada-kamp';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Babası gece çocuklara hangi takımyıldızını gösterdi?', 'Kuğu', 'Avcı', 'Aslan', 'Büyükayı', 'd', 'Metinde babanın Büyükayı takımyıldızını gösterdiği yazıyor.' FROM texts WHERE slug = 'bir-adada-kamp';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Arda''nın “Adayı bulduğumuz gibi bırakmalıyız” sözü ne anlatıyor?', 'Adaya bir daha gelmek istemediğini', 'Doğaya saygı gösterip geride çöp bırakmamak gerektiğini', 'Adada ev yapmak istediğini', 'Çadırları adada unutmak istediğini', 'b', 'Çocuklar çöpleri topladı; Arda doğayı temiz ve bozulmamış bırakmaktan söz ediyor.' FROM texts WHERE slug = 'bir-adada-kamp';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('robot-supurge-ve-sensorler', 'Robot Süpürge ve Sensörler', 'Bazı evlerde yerleri kendi kendine temizleyen küçük, yuvarlak robotlar vardır. Bunlara robot süpürge denir. Peki bu robotlar duvara çarpmadan, merdivenden düşmeden nasıl dolaşır? Bu işin sırrı sensörlerdedir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Sensör nedir?', 'Robotun tekerleği', 'Çevredeki bir değişikliği algılayan parça', 'Robotun toz haznesi', 'Robotun şarj kablosu', 'b', 'Metinde sensörün çevredeki bir değişikliği algılayan küçük bir parça olduğu yazıyor.' FROM texts WHERE slug = 'robot-supurge-ve-sensorler';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Robot bir duvara hafifçe dokunduğunda ne olur?', 'Robot hemen kapanır.', 'Robot yüksek sesle öter.', 'Robot duvarı itmeye devam eder.', 'Tampon itilir, sensör fark eder ve robot yön değiştirir.', 'd', 'Tamponun arkasındaki sensör çarpmayı fark eder, robot durur ve başka yöne döner.' FROM texts WHERE slug = 'robot-supurge-ve-sensorler';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Uçurum sensörünün gönderdiği ışık geri dönmezse bu ne demektir?', 'Önde bir boşluk, örneğin merdiven vardır.', 'Zemin çok temizdir.', 'Robotun şarjı bitmiştir.', 'Odada kimse yoktur.', 'a', 'Işık geri dönmüyorsa önde zemin yoktur, yani bir boşluk vardır.' FROM texts WHERE slug = 'robot-supurge-ve-sensorler';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu metnin ana fikri nedir?', 'Robot süpürgeler çok pahalıdır.', 'Robot süpürgeler insanlar gibi düşünür.', 'Robot süpürgeler sensörlerden gelen bilgilerle hareket eder.', 'Robot süpürgeler yalnızca halıyı temizler.', 'c', 'Metin, robotun sensörlerden gelen bilgilere göre nasıl karar verdiğini anlatıyor.' FROM texts WHERE slug = 'robot-supurge-ve-sensorler';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('kuyruklu-yildizlar', 'Kuyruklu Yıldızlar', 'Bazen gökyüzünde uzun, parlak bir kuyruğu olan bir cisim görülür. İnsanlar bunlara kuyruklu yıldız der. Ama bu ad biraz yanıltıcıdır. Kuyruklu yıldızlar aslında yıldız değildir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kuyruklu yıldızlar nelerden oluşur?', 'Sadece ateşten', 'Sıcak gazdan', 'Buz, toz ve kayadan', 'Metal ve camdan', 'c', 'Metinde kuyruklu yıldızların buz, toz ve kayadan oluştuğu yazıyor.' FROM texts WHERE slug = 'kuyruklu-yildizlar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kuyruklu yıldızın kuyruğu nasıl oluşur?', 'Güneş''e yaklaşınca ısınır, buzu gaza dönüşür ve toz yayılır.', 'Başka bir yıldıza çarpınca oluşur.', 'Dünya''nın havası onu boyar.', 'Uzaydaki rüzgâr onu dondurur.', 'a', 'Güneş''e yaklaşan kuyruklu yıldız ısınır; gaz ve toz kuyruğu oluşturur.' FROM texts WHERE slug = 'kuyruklu-yildizlar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kuyruk hangi yönü gösterir?', 'Her zaman Dünya''yı', 'Her zaman Ay''ı', 'Rastgele bir yönü', 'Her zaman Güneş''in ters yönünü', 'd', 'Güneş''ten gelen rüzgâr ve ışık gazı ve tozu geriye ittiği için kuyruk Güneş''in ters yönündedir.' FROM texts WHERE slug = 'kuyruklu-yildizlar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre Halley kuyruklu yıldızı bir dahaki sefere ne zaman görülecek?', '1986 yılında', '2061 yılında', 'Her yıl', 'Hiçbir zaman', 'b', 'Metinde Halley''in bir dahaki gelişinin 2061 yılında olacağı yazıyor.' FROM texts WHERE slug = 'kuyruklu-yildizlar';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('kayip-anahtarin-gizemi', 'Kayıp Anahtarın Gizemi', 'Pazartesi sabahı okul kütüphanesinin kapısı açılamadı. Kütüphane görevlisi Nermin Hanım bütün çantasını karıştırdı ama anahtarı bulamadı. Oysa cuma günü anahtarı her zamanki gibi çekmecesine koyduğundan emindi.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Nermin Hanım cuma günü anahtarı nereye koyduğunu düşünüyordu?', 'Cebine', 'Çekmecesine', 'Saksıya', 'Kapının üstüne', 'b', 'Metinde Nermin Hanım''ın anahtarı her zamanki gibi çekmecesine koyduğundan emin olduğu yazıyor.' FROM texts WHERE slug = 'kayip-anahtarin-gizemi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kerem dedektiflik çalışmasında ne yaptı?', 'Kediyi yakaladı', 'Çiçekleri suladı', 'Kütüphanenin kapısını açtı', 'Her şeyi not defterine yazdı', 'd', 'Kerem konuşmaları ve bulguları not defterine yazdı.' FROM texts WHERE slug = 'kayip-anahtarin-gizemi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yusuf saksının yanında ne fark etti?', 'Pati izleri ve kazılmış toprak', 'Yere düşmüş bir kitap', 'Kırık bir cam', 'Islak ayak izleri', 'a', 'Yusuf toprağın üstünde minik pati izleri ve kazılmış bir yer gördü.' FROM texts WHERE slug = 'kayip-anahtarin-gizemi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Anahtar saksıya nasıl gitmişti?', 'Rüzgâr onu uçurmuştu.', 'Bir öğrenci saklamıştı.', 'Nermin Hanım''ın cebinden düşmüş, kedi Tarçın onu saksıya sürüklemişti.', 'Nermin Hanım onu bilerek oraya koymuştu.', 'c', 'Anahtar çiçekler sulanırken düşmüş, Tarçın da onu oyuncak sanıp saksıya götürmüştü.' FROM texts WHERE slug = 'kayip-anahtarin-gizemi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Çocukların gizemi çözmesini asıl sağlayan neydi?', 'Şans eseri anahtarı bulmaları', 'Soru sorup dikkatle ipuçlarını izlemeleri', 'Öğretmenlerin onlara yardım etmesi', 'Kütüphanenin kapısını kırmaları', 'b', 'Çocuklar önce bilgi topladılar, sonra dikkatli bakarak pati izlerini fark ettiler.' FROM texts WHERE slug = 'kayip-anahtarin-gizemi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('pamukkale-travertenleri', 'Pamukkale''nin Beyaz Basamakları', 'Denizli''deki Pamukkale''yi uzaktan görenler, bir tepenin karla kaplandığını sanabilir. Ama o bembeyaz görüntü kar değildir. Bu beyaz basamaklara traverten denir. Pamukkale adını da bu pamuk gibi beyaz görüntüden alır.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Pamukkale''deki beyaz basamaklara ne ad verilir?', 'Buzul', 'Kum tepesi', 'Traverten', 'Kar örtüsü', 'c', 'Metinde bu beyaz basamaklara traverten dendiği yazıyor.' FROM texts WHERE slug = 'pamukkale-travertenleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Sıcak suya yerin altında hangi madde karışır?', 'Kalsiyum', 'Tuz', 'Demir', 'Şeker', 'a', 'Su kayaların arasından geçerken içine kalsiyum karışır.' FROM texts WHERE slug = 'pamukkale-travertenleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Hierapolis nedir?', 'Bir göl', 'Bir dağ', 'Yeni kurulmuş bir şehir', 'Pamukkale''nin yanındaki antik bir kent', 'd', 'Hierapolis, Pamukkale''nin hemen yanındaki yaklaşık iki bin yıllık antik bir kenttir.' FROM texts WHERE slug = 'pamukkale-travertenleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Pamukkale ve Hierapolis hangi yıl UNESCO Dünya Mirası Listesi''ne alındı?', '1958', '1988', '2008', '2018', 'b', 'Metinde 1988 yılında listeye alındığı belirtiliyor.' FROM texts WHERE slug = 'pamukkale-travertenleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ziyaretçilerin travertenlerde çıplak ayakla yürümesinin amacı nedir?', 'Suyun daha sıcak hissedilmesi', 'Daha hızlı yürüyebilmek', 'Ayakkabıların ıslanmaması', 'Hassas beyaz yüzeyin aşınıp kirlenmemesi', 'd', 'Ayakkabılar travertenleri aşındırıp kirletebildiği için bu kural konmuştur.' FROM texts WHERE slug = 'pamukkale-travertenleri';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('mevsimler-neden-olusur', 'Mevsimler Neden Oluşur?', 'Yazın havalar sıcak, günler uzundur. Kışın ise havalar soğur, güneş erkenden batar. Peki mevsimler neden oluşur? Pek çok kişi bunun, Dünya''nın Güneş''e bazen yaklaşıp bazen uzaklaşmasından kaynaklandığını düşünür. Ama asıl sebep başkadır.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre pek çok kişi mevsimlerin sebebi hakkında neyi yanlış düşünür?', 'Ay''ın Dünya''yı ısıttığını', 'Dünya''nın Güneş''e yaklaşıp uzaklaştığını', 'Rüzgârın mevsimleri getirdiğini', 'Bulutların güneşi kapattığını', 'b', 'Metin, mevsimlerin Güneş''e yaklaşıp uzaklaşmaktan kaynaklanmadığını belirtiyor.' FROM texts WHERE slug = 'mevsimler-neden-olusur';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Dünya''nın ekseni yaklaşık kaç derece eğiktir?', '5 derece', '45 derece', '90 derece', '23,5 derece', 'd', 'Metinde eksenin yaklaşık 23,5 derece eğik olduğu yazıyor.' FROM texts WHERE slug = 'mevsimler-neden-olusur';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yazın havalar neden daha sıcaktır?', 'Güneş ışınları daha dik gelip yeri daha çok ısıttığı için', 'Dünya daha hızlı döndüğü için', 'Güneş daha büyük olduğu için', 'Gece hiç olmadığı için', 'a', 'Dik gelen ışınlar yeri daha çok ısıtır ve günler de uzar.' FROM texts WHERE slug = 'mevsimler-neden-olusur';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'El feneri deneyi neyi göstermektedir?', 'Fenerin pilinin ne kadar dayandığını', 'Işığın renklerini', 'Eğik gelen ışığın daha geniş alana yayılıp daha soluk olduğunu', 'Kâğıdın ışığı yansıttığını', 'c', 'Eğik tutulan fenerin ışığı geniş ve soluk bir alana yayılır; kışın güneş ışınları da böyledir.' FROM texts WHERE slug = 'mevsimler-neden-olusur';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Türkiye''de yaz yaşanırken Avustralya''da neden kış yaşanır?', 'Avustralya Güneş''e daha uzak olduğu için', 'İki ülke farklı yarım kürelerde olduğu için', 'Avustralya''da hiç güneş doğmadığı için', 'Avustralya çok küçük olduğu için', 'b', 'Bir yarım küre Güneş''e doğru eğikken diğeri Güneş''ten uzağa eğiktir.' FROM texts WHERE slug = 'mevsimler-neden-olusur';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('geleneksel-turk-okculugu', 'Geleneksel Türk Okçuluğu', 'Okçuluk, Türklerin binlerce yıldır uğraştığı bir spordur. Orta Asya''nın geniş bozkırlarında yaşayan Türkler için ok ve yay, hem avlanmak hem de kendini korumak için önemliydi. Usta atlı okçular, dörtnala giden atın üzerinden bile hedefi vurabiliyordu.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Türk yayı hangi malzemelerden yapılır?', 'Sadece demirden', 'Plastik ve camdan', 'Tek bir tahtadan', 'Ağaç, boynuz ve hayvan sinirinden', 'd', 'Türk yayı ağaç, boynuz ve sinirin özel tutkalla birleştirilmesiyle yapılır.' FROM texts WHERE slug = 'geleneksel-turk-okculugu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Okmeydanı hangi şehirdeydi?', 'İstanbul', 'Bursa', 'Konya', 'Edirne', 'a', 'Metinde Osmanlı döneminde İstanbul''da Okmeydanı adında bir alan olduğu yazıyor.' FROM texts WHERE slug = 'geleneksel-turk-okculugu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Menzil taşı ne zaman dikilirdi?', 'Bir okçu ilk kez yay tuttuğunda', 'Bir yay tamamlandığında', 'Bir okçu rekor kırdığında, okun düştüğü yere', 'Her bayramda meydanın ortasına', 'c', 'Rekor kırıldığında okun düştüğü yere menzil taşı dikilirdi.' FROM texts WHERE slug = 'geleneksel-turk-okculugu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bir Türk yayının yapımı neden uzun sürerdi?', 'Ustalar çok yavaş çalıştığı için', 'Tutkalın ve katmanların kuruması beklendiği için', 'Malzemeler çok uzaktan geldiği için', 'Yaylar çok büyük olduğu için', 'b', 'Tutkal ve katmanların kuruması için sabırla beklemek gerekirdi.' FROM texts WHERE slug = 'geleneksel-turk-okculugu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre geleneksel okçuluk neden yalnızca bir spor değildi?', 'Okçulara sabır, dürüstlük ve saygı gibi değerler de öğretilirdi.', 'Okçular sadece para kazanmak için yarışırdı.', 'Okçuluk yalnızca savaşta yapılırdı.', 'Okçular hiç antrenman yapmazdı.', 'a', 'Usta okçular atış tekniklerinin yanında sabır, dürüstlük ve saygıyı da öğretirdi.' FROM texts WHERE slug = 'geleneksel-turk-okculugu';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('ruzgar-turbinleri', 'Rüzgâr Türbinleri', 'Tepelerde ya da deniz kıyısında dev pervanelere benzeyen beyaz kuleler görmüşsündür. Bunlara rüzgâr türbini denir. Rüzgâr türbinleri, esen rüzgârın gücünü elektriğe dönüştüren makinelerdir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Türbinde hareketi elektriğe çeviren makinenin adı nedir?', 'Pervane', 'Kule', 'Jeneratör', 'Kablo', 'c', 'Metinde dönen milin jeneratörü çalıştırdığı ve jeneratörün hareketi elektriğe çevirdiği yazıyor.' FROM texts WHERE slug = 'ruzgar-turbinleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Rüzgâr türbinleri neden çok yüksek yapılır?', 'Yükseklerde rüzgâr daha güçlü ve düzenli estiği için', 'Uzaktan güzel göründükleri için', 'Kuşlar yakına gelmesin diye', 'Yerde yeterli yer olmadığı için', 'a', 'Yerden yükseldikçe rüzgâr daha güçlü ve daha düzenli eser.' FROM texts WHERE slug = 'ruzgar-turbinleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Rüzgâr türbinlerinin en büyük faydası nedir?', 'Çok sessiz çalışmaları', 'Hiç bakım gerektirmemeleri', 'Rüzgârı durdurmaları', 'Havayı kirleten duman çıkarmadan elektrik üretmeleri', 'd', 'Metinde en büyük faydanın havayı kirletmeden elektrik üretmek olduğu yazıyor.' FROM texts WHERE slug = 'ruzgar-turbinleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Rüzgâr enerjisi neden başka enerji kaynaklarıyla birlikte kullanılır?', 'Rüzgâr enerjisi çok tehlikeli olduğu için', 'Rüzgâr her zaman aynı hızda esmediği için', 'Türbinler yalnızca geceleri çalıştığı için', 'Rüzgâr bir gün tükeneceği için', 'b', 'Rüzgâr durunca türbinler de durur; bu yüzden başka kaynaklar da gerekir.' FROM texts WHERE slug = 'ruzgar-turbinleri';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('uluslararasi-uzay-istasyonu', 'Uluslararası Uzay İstasyonu', 'Gece gökyüzüne baktığında hızla ilerleyen, yanıp sönmeyen parlak bir nokta görebilirsin. Bu nokta bir uçak değil, Uluslararası Uzay İstasyonu olabilir. İstasyon, Dünya''nın yaklaşık 400 kilometre yukarısında dolaşan dev bir laboratuvardır.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Uzay istasyonu Dünya''nın yaklaşık kaç kilometre yukarısında dolaşır?', '40 kilometre', '400 kilometre', '4.000 kilometre', '40.000 kilometre', 'b', 'Metinde istasyonun yaklaşık 400 kilometre yukarıda dolaştığı yazıyor.' FROM texts WHERE slug = 'uluslararasi-uzay-istasyonu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Uzay istasyonu nasıl kuruldu?', 'Tek bir roketle bütün hâlinde fırlatıldı.', 'Ay''da yapılıp Dünya''nın çevresine getirildi.', 'Tek bir ülke tarafından bir yılda yapıldı.', 'Parça parça uzaya taşınıp orada birleştirildi.', 'd', 'Bölümler yıllar boyunca farklı roketlerle taşındı ve uzayda birbirine eklendi.' FROM texts WHERE slug = 'uluslararasi-uzay-istasyonu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Astronotlar bir günde neden on altı kez gün doğumu izler?', 'İstasyon Dünya''nın çevresini yaklaşık 90 dakikada bir dolaştığı için', 'Uzayda Güneş çok hızlı hareket ettiği için', 'İstasyonun pencereleri çok büyük olduğu için', 'Astronotlar hiç uyumadığı için', 'a', 'Her 90 dakikalık turda bir gün doğumu ve bir gün batımı yaşanır.' FROM texts WHERE slug = 'uluslararasi-uzay-istasyonu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Astronotların her gün spor yapması neden gereklidir?', 'Yarışmalara hazırlanmak için', 'İstasyonu ısıtmak için', 'Kaslarının ve kemiklerinin zayıflamaması için', 'Uykularını getirmek için', 'c', 'Ağırlıksız ortamda kaslar ve kemikler zayıflayabildiği için spor yapmaları gerekir.' FROM texts WHERE slug = 'uluslararasi-uzay-istasyonu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Uzay istasyonuna giden ilk Türk astronot kimdir?', 'Nasuh Mahruki', 'Alper Gezeravcı', 'Piri Reis', 'Cahit Arf', 'b', 'Alper Gezeravcı 2024 yılının ocak ayında istasyona giden ilk Türk astronot oldu.' FROM texts WHERE slug = 'uluslararasi-uzay-istasyonu';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('bitkiler-nasil-beslenir', 'Bitkiler Nasıl Beslenir?', 'Hayvanlar ve insanlar karnı acıktığında yemek yer. Peki bitkiler nasıl beslenir? Bir ağacın ağzı olmadığı hâlde nasıl büyüyüp kocaman olabildiğini hiç düşündün mü? Bitkiler besinlerini dışarıdan hazır almaz, onları kendileri üretir. Bu olaya fotosentez denir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Fotosentez için bitkinin hangi üç şeye ihtiyacı vardır?', 'Güneş ışığı, su ve karbondioksit', 'Toprak, taş ve kum', 'Oksijen, şeker ve tuz', 'Rüzgâr, kar ve gölge', 'a', 'Metinde fotosentez için güneş ışığı, su ve karbondioksit gerektiği yazıyor.' FROM texts WHERE slug = 'bitkiler-nasil-beslenir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Klorofilin görevi nedir?', 'Suyu topraktan çekmek', 'Bitkiyi böceklerden korumak', 'Güneş ışığını yakalamak', 'Kökleri büyütmek', 'c', 'Klorofil, güneş ışığını yakalayan minik bir güneş paneli gibi çalışır.' FROM texts WHERE slug = 'bitkiler-nasil-beslenir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Su yapraklara nasıl ulaşır?', 'Yağmurla doğrudan yapraklara yağar.', 'Havadan yaprak deliklerine girer.', 'Çiçeklerden aşağı akar.', 'Köklerle emilir ve gövdedeki ince borularla taşınır.', 'd', 'Su kökler tarafından emilir ve gövdedeki borularla yapraklara taşınır.' FROM texts WHERE slug = 'bitkiler-nasil-beslenir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Fotosentez sırasında bitki havaya hangi gazı bırakır?', 'Karbondioksit', 'Oksijen', 'Duman', 'Buhar', 'b', 'Metinde bitkinin fotosentez sırasında oksijeni havaya bıraktığı yazıyor.' FROM texts WHERE slug = 'bitkiler-nasil-beslenir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Karanlık dolapta bırakılan bitkinin yaprakları neden sararır?', 'Dolap çok soğuk olduğu için', 'Bitki çok fazla su içtiği için', 'Dolapta çok fazla oksijen olduğu için', 'Işık olmadan bitki besinini üretemediği için', 'd', 'Fotosentez ışık gerektirir; ışıksız kalan bitki besin üretemez.' FROM texts WHERE slug = 'bitkiler-nasil-beslenir';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('mimar-sinan', 'Mimar Sinan', 'Mimar Sinan, Türk tarihinin en büyük mimarlarından biridir. Yaklaşık 1490 yılında Kayseri yakınlarındaki Ağırnas köyünde doğdu. Gençliğinde İstanbul''a getirildi ve yeniçeri ocağına katıldı. Burada marangozluk ve yapı işlerini öğrendi.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Mimar Sinan nerede doğdu?', 'İstanbul''da', 'Edirne''de', 'Kayseri yakınlarındaki Ağırnas köyünde', 'Bursa''da', 'c', 'Metinde Sinan''ın Kayseri yakınlarındaki Ağırnas köyünde doğduğu yazıyor.' FROM texts WHERE slug = 'mimar-sinan';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Sinan orduyla katıldığı seferlerde neler yaptı?', 'Köprüler, gemiler ve başka yapılar inşa etti.', 'Sadece kitap yazdı.', 'Askerlere yemek pişirdi.', 'Harita çizdi.', 'a', 'Seferlerde köprüler, gemiler ve başka yapılar inşa ettiği anlatılıyor.' FROM texts WHERE slug = 'mimar-sinan';
