INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Sinan''ın yapılarının pek çoğunun bugün hâlâ ayakta olmasının sebeplerinden biri ne olabilir?', 'Hiç kullanılmamış olmaları', 'Çok küçük yapılmış olmaları', 'Sinan''ın depreme dayanıklılığa önem vermesi', 'Hepsinin yeniden yapılmış olması', 'c', 'Metinde Sinan''ın binaların depremlere dayanıklı olmasına önem verdiği anlatılıyor.' FROM texts WHERE slug = 'mimar-sinan';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('everest-tirmanisi', 'Everest''e Tırmanış', 'Everest, dünyanın en yüksek dağıdır. Asya''daki Himalaya Dağları''nda, Nepal ile Çin sınırında yer alır. Zirvesi deniz seviyesinden yaklaşık 8.849 metre yüksekliktedir. Bu, yolcu uçaklarının uçtuğu yüksekliğe oldukça yakındır.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Everest''in zirvesi deniz seviyesinden yaklaşık kaç metre yüksektir?', '2.849 metre', '5.849 metre', '8.849 metre', '12.849 metre', 'c', 'Metinde zirvenin yaklaşık 8.849 metre yükseklikte olduğu yazıyor.' FROM texts WHERE slug = 'everest-tirmanisi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre Everest''e tırmanmanın en büyük zorluğu nedir?', 'Havadaki oksijenin azalması', 'Yolların çok kalabalık olması', 'Vahşi hayvanlar', 'Dağın çok uzakta olması', 'a', 'Metinde en büyük zorluğun havanın incelmesi, yani oksijenin azalması olduğu belirtiliyor.' FROM texts WHERE slug = 'everest-tirmanisi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Dağcılar neden yüksek kamplara çıkıp tekrar aşağı iner?', 'Unuttukları eşyaları almak için', 'Manzarayı izlemek için', 'Şerpalarla buluşmak için', 'Vücutlarının az oksijene uyum sağlaması için', 'd', 'Bu gidip gelmeler vücudun yüksekliğe ve az oksijene alışmasını sağlar.' FROM texts WHERE slug = 'everest-tirmanisi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Everest''in zirvesine ilk kez hangi yıl ulaşıldı?', '1923', '1953', '1995', '2003', 'b', 'Edmund Hillary ve Tenzing Norgay zirveye 1953 yılında ulaştı.' FROM texts WHERE slug = 'everest-tirmanisi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Hillary ve Tenzing''in başarısı bize en çok neyi gösterir?', 'İş birliği ve güvenin zor hedeflere ulaştırdığını', 'Dağcılığın kolay bir iş olduğunu', 'Yalnız başına tırmanmanın daha iyi olduğunu', 'Oksijen tüpüne gerek olmadığını', 'a', 'Metinde ikisinin birlikte çalışarak ve birbirine güvenerek başardığı vurgulanıyor.' FROM texts WHERE slug = 'everest-tirmanisi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('kasgarli-mahmud-ve-divanu-lugatit-turk', 'Kaşgarlı Mahmud ve Divanu Lugati''t-Türk', 'Yaklaşık bin yıl önce, Orta Asya''daki Kaşgar şehrinde yetişen Mahmud adında bir bilgin, hayatını Türk dilini araştırmaya adadı. Bugün onu Kaşgarlı Mahmud adıyla tanıyoruz. Onun yazdığı Divanu Lugati''t-Türk, Türk dilinin bilinen en eski ve en önemli sözlüklerinden biri kabul edilir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kaşgarlı Mahmud Divanu Lugati''t-Türk''ü hazırlarken özellikle kimlerin Türkçe öğrenmesini amaçlamıştı?', 'Çinlilerin', 'Arapça konuşanların', 'Avrupalıların', 'Türk çocuklarının', 'b', 'Metinde Mahmud''un özellikle Arapça konuşanların Türkçeyi öğrenmesi için eseri hazırladığı yazıyor.' FROM texts WHERE slug = 'kasgarli-mahmud-ve-divanu-lugatit-turk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kaşgarlı Mahmud kelimeleri nasıl topladı?', 'Eski kitapları kopyalayarak', 'Başka bir sözlüğü çevirerek', 'Öğrencilerine sorarak', 'Türk boylarını dolaşıp insanların konuşmalarını not alarak', 'd', 'Yıllarca Türk boylarının yaşadığı yerleri dolaştı ve kelimeleri insanların ağzından not etti.' FROM texts WHERE slug = 'kasgarli-mahmud-ve-divanu-lugatit-turk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Divanu Lugati''t-Türk''te kelimelerin anlamlarından başka neler bulunur?', 'Atasözleri, şiirler, günlük hayat bilgileri ve bir dünya haritası', 'Matematik problemleri', 'Yemek tarifleri ve resimli masallar', 'Yalnızca kral listeleri', 'a', 'Kitapta atasözleri, şiirler, günlük hayata dair bilgiler ve yuvarlak bir dünya haritası vardır.' FROM texts WHERE slug = 'kasgarli-mahmud-ve-divanu-lugatit-turk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Eserin günümüze ulaşan nüshası hakkında hangisi doğrudur?', 'Yüzlerce nüshası vardır.', 'Hiçbir nüshası kalmamıştır.', 'Tek bir el yazması nüshası vardır ve Millet Kütüphanesi''nde korunur.', 'Tek nüshası Bağdat''ta bir müzededir.', 'c', 'Eserin tek el yazması nüshası İstanbul''da bulunmuş ve Millet Kütüphanesi''nde korunmaktadır.' FROM texts WHERE slug = 'kasgarli-mahmud-ve-divanu-lugatit-turk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metinde kitabın bir hazineye benzetilmesinin sebebi nedir?', 'Kitabın altınla süslenmiş olması', 'Kitabın çok pahalıya satılması', 'Kitabın gizli bir yerde saklanmış olması', 'Kitabın o dönemin Türklerinin yaşamını ve değerlerini de anlatması', 'd', 'Kitap kelimelerin yanında Türklerin ne yediğini, nasıl eğlendiğini ve neye değer verdiğini de anlatır.' FROM texts WHERE slug = 'kasgarli-mahmud-ve-divanu-lugatit-turk';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('okyanusun-derinlikleri', 'Okyanusun Derinlikleri', 'Dünya yüzeyinin üçte ikisinden fazlası okyanuslarla kaplıdır. Buna rağmen okyanus tabanının büyük bir bölümü hâlâ ayrıntılı olarak keşfedilmemiştir. Hatta okyanus tabanının haritası, Ay yüzeyinin haritası kadar ayrıntılı çıkarılamamıştır. Peki bu keşfi bu kadar zorlaştıran nedir?
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Okyanusun çok derin bölgelerinde neden bitki yaşamaz?', 'Su çok tuzlu olduğu için', 'Balıklar bütün bitkileri yediği için', 'Fotosentez için gereken güneş ışığı olmadığı için', 'Su çok sıcak olduğu için', 'c', 'Bin metrenin altında neredeyse hiç ışık kalmaz; bitkiler ışık olmadan besin üretemez.' FROM texts WHERE slug = 'okyanusun-derinlikleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Challenger Derinliği yaklaşık kaç metre derinliktedir?', '11 bin metre', '1 bin metre', '200 metre', '50 bin metre', 'a', 'Metinde Challenger Derinliği''nin yaklaşık 11 bin metre derinlikte olduğu yazıyor.' FROM texts WHERE slug = 'okyanusun-derinlikleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metindeki Everest karşılaştırması neyi anlatmak için yapılmıştır?', 'Everest''in denizin içinde olduğunu', 'Dağcıların dalış da yaptığını', 'Everest''in aslında alçak bir dağ olduğunu', 'Challenger Derinliği''nin Everest''in yüksekliğinden bile daha derin olduğunu', 'd', 'Everest buraya konsa bile zirvesi suyun altında kalırdı; yani çukur Everest''ten daha derindir.' FROM texts WHERE slug = 'okyanusun-derinlikleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Biyolüminesans nedir?', 'Suyun basıncı', 'Canlıların kendi ışığını üretmesi', 'Okyanus tabanının haritası', 'Bir dalış aracının adı', 'b', 'Metinde canlıların ışık üretmesine biyolüminesans dendiği açıklanıyor.' FROM texts WHERE slug = 'okyanusun-derinlikleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu metnin ana fikri nedir?', 'Okyanuslar tamamen keşfedilmiştir.', 'Derin denizlerde hiç canlı yaşamaz.', 'Okyanus derinlikleri zor koşullarına rağmen canlılarla ve keşfedilmeyi bekleyen sırlarla doludur.', 'Denizaltılar okyanusu kirletir.', 'c', 'Metin karanlık ve basınç gibi zorlukları anlatırken derinliklerin canlılarla ve sırlarla dolu olduğunu vurguluyor.' FROM texts WHERE slug = 'okyanusun-derinlikleri';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('baykuslar-gece-avcilari', 'Baykuşlar Geceleri Nasıl Avlanır?', 'Baykuş bir gece kuşudur. Gündüz ağaç kovuklarında uyur. Hava kararınca uyanır ve avlanmaya çıkar.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Baykuş gündüzleri ne yapar?', 'Uyur', 'Avlanır', 'Yuva yapar', 'Göç eder', 'a', 'Metinde baykuşun gündüz ağaç kovuklarında uyuduğu yazıyor.' FROM texts WHERE slug = 'baykuslar-gece-avcilari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Baykuş gözlerini oynatamadığı için ne yapar?', 'Gözlerini kapatır', 'Uçmayı bırakır', 'Başını çevirir', 'Yere iner', 'c', 'Baykuş gözlerini oynatamaz, bunun yerine başını çevirir.' FROM texts WHERE slug = 'baykuslar-gece-avcilari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Fare, baykuşun geldiğini neden duymaz?', 'Baykuş çok uzakta olduğu için', 'Baykuş çok sessiz uçtuğu için', 'Fare uyuduğu için', 'Rüzgâr estiği için', 'b', 'Tüylerinin kenarları yumuşak olduğu için baykuş sessiz uçar.' FROM texts WHERE slug = 'baykuslar-gece-avcilari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu metin en çok neyi anlatıyor?', 'Baykuşların yuva yapmasını', 'Farelerin yaşamını', 'Çiftçilerin işlerini', 'Baykuşların gece nasıl avlandığını', 'd', 'Metin baykuşun gözlerini, kulaklarını ve sessiz uçuşunu, yani nasıl avlandığını anlatıyor.' FROM texts WHERE slug = 'baykuslar-gece-avcilari';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('mikroplar-ve-el-yikama', 'Mikroplar ve El Yıkama', 'Mikroplar çok küçük canlılardır. O kadar küçüktürler ki onları gözümüzle göremeyiz. Onları görmek için mikroskop denen bir alet kullanırız.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Mikropları görmek için hangi aleti kullanırız?', 'Dürbün', 'Gözlük', 'Mikroskop', 'Pusula', 'c', 'Metinde mikropları görmek için mikroskop kullanıldığı yazıyor.' FROM texts WHERE slug = 'mikroplar-ve-el-yikama';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Hangisi yararlı bir mikrobun yaptığı iştir?', 'Sütü yoğurda çevirmek', 'Nezle yapmak', 'İshale neden olmak', 'Kapı kollarını kirletmek', 'a', 'Sütü yoğurda çeviren minik canlılar yararlı mikroplardır.' FROM texts WHERE slug = 'mikroplar-ve-el-yikama';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ellerimizi en az ne kadar süre yıkamalıyız?', 'Beş saniye', 'Yirmi saniye', 'İki dakika', 'Bir saat', 'b', 'Metne göre el yıkama en az yirmi saniye sürmelidir.' FROM texts WHERE slug = 'mikroplar-ve-el-yikama';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre ellerimizi yıkamak neden önemlidir?', 'Ellerimiz güzel koksun diye', 'Sabun bitsin diye', 'Havlu ıslansın diye', 'Hastalık yapan mikroplardan korunmak için', 'd', 'Hastalık yapan mikroplar ellerle taşınır; el yıkamak bizi korur.' FROM texts WHERE slug = 'mikroplar-ve-el-yikama';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('bisiklet-surmeyi-ogreniyorum', 'Bisiklet Sürmeyi Öğreniyorum', 'Elif''in yeni bir bisikleti vardı. Bisikleti kırmızıydı ve zili parlaktı. Ama Elif henüz bisiklet süremiyordu. Her gün parktaki çocukları izliyor, onlar gibi rüzgârı yüzünde hissetmek istiyordu.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Babası Elif''e önce ne taktı?', 'Zilini', 'Kaskını', 'Gözlüğünü', 'Eldivenini', 'b', 'Metinde babasının önce Elif''e kaskını taktığı yazıyor.' FROM texts WHERE slug = 'bisiklet-surmeyi-ogreniyorum';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Babası Elif''e hangi öğüdü verdi?', 'Yavaş gitmesini', 'Geriye bakmasını', 'Önüne bakıp pedalları durmadan çevirmesini', 'Eve dönmesini', 'c', 'Babası ''Önüne bak, geriye değil. Pedalları durmadan çevir.'' dedi.' FROM texts WHERE slug = 'bisiklet-surmeyi-ogreniyorum';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Elif düştüğünde canı neden yanmadı?', 'Babası onu tuttuğu için', 'Bisiklet durduğu için', 'Kumlara düştüğü için', 'Dizinde koruyucu olduğu için', 'd', 'Dizindeki koruyucu sayesinde canı yanmadı.' FROM texts WHERE slug = 'bisiklet-surmeyi-ogreniyorum';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu hikâyenin ana fikri nedir?', 'Düşünce vazgeçmeyip yeniden denemek önemlidir', 'Bisiklet çok tehlikelidir', 'Parklar pazar günleri kalabalıktır', 'Kırmızı bisikletler daha hızlıdır', 'a', 'Hikâye ''Önemli olan yeniden kalkmaktı.'' diye biter.' FROM texts WHERE slug = 'bisiklet-surmeyi-ogreniyorum';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('annemle-kurabiye-yapiyoruz', 'Annemle Kurabiye Yapıyoruz', 'Bugün cumartesi. Annemle kurabiye yapacağız. Önce ellerimizi yıkadık. Sonra önlüklerimizi taktık.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Tarifte kaç su bardağı un vardı?', 'İki', 'Bir', 'Üç', 'Dört', 'c', 'Metinde tarifte üç su bardağı un yazdığı belirtiliyor.' FROM texts WHERE slug = 'annemle-kurabiye-yapiyoruz';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kurabiyeler fırında kaç dakika pişti?', 'On dakika', 'Yirmi dakika', 'Beş dakika', 'On beş dakika', 'd', 'Saati on beş dakikaya kurdular.' FROM texts WHERE slug = 'annemle-kurabiye-yapiyoruz';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Tepsiyi fırına neden annesi yerleştirdi?', 'Fırın çok sıcak olduğu için', 'Tepsi çok büyük olduğu için', 'Çocuk uyuduğu için', 'Kurabiyeler bitmediği için', 'a', 'Fırın çok sıcak olduğu için tepsiyi annesi yerleştirdi.' FROM texts WHERE slug = 'annemle-kurabiye-yapiyoruz';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yirmi dört kurabiyenin yarısı komşuya götürüldüyse evde kaç kurabiye kalmıştır?', 'Altı', 'On iki', 'Yirmi', 'On sekiz', 'b', 'Yirmi dördün yarısı on ikidir; on iki kurabiye kalır.' FROM texts WHERE slug = 'annemle-kurabiye-yapiyoruz';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('saturnun-halkalari', 'Satürn''ün Halkaları', 'Satürn, Güneş''e en yakın altıncı gezegendir. Güneş''in çevresindeki bir turunu yaklaşık otuz yılda tamamlar. Onu diğer gezegenlerden ayıran en önemli özelliği, çevresini saran görkemli halkalarıdır. Bu halkalar uzaktan bakınca düz ve katı bir tabak gibi görünür. Ama aslında öyle değildir. Bu halkalar küçük bir teleskopla bile görülebilir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Satürn''ün halkaları çoğunlukla neden oluşur?', 'Demirden', 'Gaz bulutundan', 'Buz parçalarından', 'Kumdan', 'c', 'Metne göre halkaları oluşturan parçaların çoğu buzdur.' FROM texts WHERE slug = 'saturnun-halkalari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Galileo halkaları neye benzetti?', 'Bir tabağa', 'Bir yüzüğe', 'Bir şapkaya', 'Kulaklara', 'd', 'Teleskobu güçlü olmadığı için halkaları gezegenin iki yanındaki kulaklara benzetti.' FROM texts WHERE slug = 'saturnun-halkalari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Cassini nedir?', 'Satürn''ü inceleyen bir uzay aracı', 'Bir yıldız', 'Satürn''ün bir halkası', 'Bir bilim insanı', 'a', 'Cassini, Satürn''ün çevresinde dolaşan bir uzay aracıdır.' FROM texts WHERE slug = 'saturnun-halkalari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Satürn''ün halkaları neden katı bir tabak değildir?', 'Çok sıcak oldukları için', 'Ayrı ayrı dönen milyarlarca parçadan oluştukları için', 'Işık saçtıkları için', 'Gezegenden çok uzak oldukları için', 'b', 'Halkalar tek parça değil, durmadan dönen milyarlarca parçadan oluşur.' FROM texts WHERE slug = 'saturnun-halkalari';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('okul-kutuphanesinde-bir-gun', 'Okul Kütüphanesinde Bir Gün', 'Salı günleri Can''ın en sevdiği gündü, çünkü o gün sınıfça okul kütüphanesine gidiyorlardı. Kütüphane, okulun ikinci katındaydı. Kapıdan girer girmez kitapların hoş kokusu burnuna geldi.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Sınıf kütüphaneye hangi gün gidiyordu?', 'Pazartesi', 'Cuma', 'Salı', 'Perşembe', 'c', 'Metinde salı günleri kütüphaneye gittikleri yazıyor.' FROM texts WHERE slug = 'okul-kutuphanesinde-bir-gun';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Uzay kitapları hangi raftaydı?', 'Bilim', 'Masallar', 'Şiirler', 'Hayvanlar', 'a', 'Selma Hanım uzay kitaplarının bilim rafında olduğunu söyledi.' FROM texts WHERE slug = 'okul-kutuphanesinde-bir-gun';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Can kitabı ne zamana kadar geri getirmelidir?', 'Ertesi gün', 'Bir ay içinde', 'Bir hafta içinde', 'İki hafta içinde', 'd', 'Selma Hanım kitabın iki hafta içinde getirilmesini istedi.' FROM texts WHERE slug = 'okul-kutuphanesinde-bir-gun';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Can kütüphaneyi neden bir hazine odasına benzetiyor?', 'İçinde altınlar olduğu için', 'Kitaplarda pek çok macera ve bilgi olduğu için', 'Kapısı kilitli olduğu için', 'Çok eski bir oda olduğu için', 'b', 'Kitaplar, içlerinde binlerce macera ve bilgi saklar.' FROM texts WHERE slug = 'okul-kutuphanesinde-bir-gun';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('trenle-uzun-yolculuk', 'Trenle Uzun Yolculuk', 'Deniz ve ailesi, kış tatilinde Kars''taki dedesini ziyaret etmeye karar verdi. Bu kez uçakla değil, trenle gideceklerdi. Ankara''dan kalkan tren, Kars''a yaklaşık bir günde varacaktı. Deniz çantasına bir defter, boya kalemleri ve en sevdiği kitabı koydu.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Deniz''in dedesi hangi şehirde yaşıyor?', 'Ankara', 'Kars', 'Sivas', 'Erzurum', 'b', 'Deniz ve ailesi Kars''taki dedesini ziyaret etmeye gidiyor.' FROM texts WHERE slug = 'trenle-uzun-yolculuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Tren tünele girince ne oldu?', 'Tren durdu', 'Kar yağmaya başladı', 'Her yer karardı', 'Deniz uyudu', 'c', 'Tren tünele girince her yer bir anda karardı.' FROM texts WHERE slug = 'trenle-uzun-yolculuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Deniz sabah pencereden ne gördü?', 'Denizi', 'Yeşil tarlaları', 'Şehrin binalarını', 'Karla kaplı dağları ve evleri', 'd', 'Sabah dağlar, ağaçlar ve evler karla kaplanmıştı.' FROM texts WHERE slug = 'trenle-uzun-yolculuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Deniz yolculuğun neden kendi başına bir macera olduğunu söyledi?', 'Yolda pek çok yeni ve ilginç şey yaşadığı için', 'Tren bozulduğu için', 'Yolda kaybolduğu için', 'Dedesini göremediği için', 'a', 'Tüneller, yemekli vagon, ranzada uyumak ve karlı manzara Deniz için yeni deneyimlerdi.' FROM texts WHERE slug = 'trenle-uzun-yolculuk';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('voleybol-ve-takim-ruhu', 'Voleybol ve Takım Ruhu', 'Voleybol, file ile ikiye ayrılan bir sahada oynanan bir takım sporudur. Her takımın sahada altı oyuncusu bulunur. Amaç, topu filenin üzerinden karşı sahaya geçirmek ve rakip sahada yere düşürmektir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Sahada her takımın kaç oyuncusu olur?', 'Beş', 'Yedi', 'Altı', 'On bir', 'c', 'Metne göre her takımın sahada altı oyuncusu bulunur.' FROM texts WHERE slug = 'voleybol-ve-takim-ruhu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bir takım topa en fazla kaç kez dokunabilir?', 'Bir', 'İki', 'Dört', 'Üç', 'd', 'Takım topu karşıya göndermeden önce en fazla üç kez dokunabilir.' FROM texts WHERE slug = 'voleybol-ve-takim-ruhu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Oyuncular neden ''Benim!'' diye bağırır?', 'Topa kimin gideceğini belirtmek için', 'Rakibi korkutmak için', 'Hakemi çağırmak için', 'Oyunu durdurmak için', 'a', 'Oyuncular ''Benim!'' diyerek topa kimin gideceğini söyler.' FROM texts WHERE slug = 'voleybol-ve-takim-ruhu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metnin ana fikri nedir?', 'Smaç vuran oyuncu en önemli oyuncudur', 'Voleybolda başarı, oyuncuların birlikte çalışmasıyla gelir', 'Voleybol çok eski bir spordur', 'Voleybol yalnızca Amerika''da oynanır', 'b', 'Metin, kimsenin tek başına sayı kazanamadığını ve her oyuncunun zincirin bir halkası olduğunu anlatır.' FROM texts WHERE slug = 'voleybol-ve-takim-ruhu';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('dronlar', 'Gökyüzünün Yardımcıları: Dronlar', 'Gökyüzünde vızıldayarak uçan küçük bir araç gördün mü hiç? Büyük olasılıkla bu bir drondu. Dronlar, içinde pilot olmayan uçan araçlardır. Bu yüzden onlara insansız hava aracı da denir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Çoğu dronun kaç pervanesi vardır?', 'Dört', 'İki', 'Altı', 'Bir', 'a', 'Metinde çoğu dronun dört pervanesi olduğu yazıyor.' FROM texts WHERE slug = 'dronlar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Dron nasıl havalanır?', 'Kanatlarını çırparak', 'Gaz balonuyla', 'Pervaneleri havayı aşağı iterek', 'Rüzgârla sürüklenerek', 'c', 'Pervaneler hızla dönüp havayı aşağı iter, böylece dron havalanır.' FROM texts WHERE slug = 'dronlar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Havalimanlarının yakınında neden dron uçurulmaz?', 'Pil çabuk bittiği için', 'Uçaklar için tehlikeli olabileceği için', 'Kamera çalışmadığı için', 'Orada rüzgâr hiç esmediği için', 'b', 'Dronlar uçaklar için tehlike oluşturabilir.' FROM texts WHERE slug = 'dronlar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Hangisi metinde sayılan dron kullanım alanlarından biri değildir?', 'Tarlaları kontrol etmek', 'Yangını izlemek', 'Enkazda insan aramak', 'Okulda ders anlatmak', 'd', 'Metinde dronların ders anlattığından söz edilmiyor.' FROM texts WHERE slug = 'dronlar';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('ahtapotun-zekasi', 'Ahtapotun Şaşırtıcı Zekâsı', 'Denizlerde yaşayan ahtapot, hayvanlar dünyasının en zeki canlılarından biri olarak kabul edilir. Onun vücudu da en az zekâsı kadar şaşırtıcıdır.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ahtapotun kaç kalbi vardır?', 'Bir', 'İki', 'Üç', 'Sekiz', 'c', 'Metne göre ahtapotun üç kalbi vardır.' FROM texts WHERE slug = 'ahtapotun-zekasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ahtapot neden küçük deliklerden geçebilir?', 'Vücudunda kemik olmadığı için', 'Çok hızlı yüzdüğü için', 'Kollarını kısalttığı için', 'Rengini değiştirdiği için', 'a', 'Vücudunda kemik bulunmadığı için dar yerlerden sıyrılabilir.' FROM texts WHERE slug = 'ahtapotun-zekasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ahtapotun kanı ne renktir?', 'Kırmızı', 'Yeşil', 'Sarı', 'Mavi', 'd', 'Metinde ahtapotun kanının mavi olduğu yazıyor.' FROM texts WHERE slug = 'ahtapotun-zekasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ahtapot tehlike anında ne yapar?', 'Uyur', 'Mürekkep püskürtür ve kaybolur', 'Kıyıya çıkar', 'Kabuğuna saklanır', 'b', 'Tehlike yaklaşınca koyu bir mürekkep püskürtüp bulutun arkasında kaybolur.' FROM texts WHERE slug = 'ahtapotun-zekasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Aşağıdakilerden hangisi ahtapotun zeki olduğunu gösterir?', 'Sekiz kolu olması', 'Denizde yaşaması', 'Kapaklı kavanozları açmayı öğrenmesi', 'Mavi kanı olması', 'c', 'Kavanoz açmayı öğrenmek, problem çözebildiğini gösterir; diğerleri vücut özellikleridir.' FROM texts WHERE slug = 'ahtapotun-zekasi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('elektrik-ve-guvenli-kullanim', 'Elektrik Nedir, Nasıl Güvenle Kullanılır?', 'Sabah lambayı yakmak, buzdolabından soğuk süt almak, akşam televizyon izlemek... Bütün bunları elektrik sayesinde yapabiliriz. Peki elektrik nedir?
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Elektrik kabloları neden genellikle bakırdan yapılır?', 'Bakır çok hafif olduğu için', 'Bakır iyi bir iletken olduğu için', 'Bakır yalıtkan olduğu için', 'Bakır parlak olduğu için', 'b', 'Bakır elektriği kolayca ileten bir metaldir.' FROM texts WHERE slug = 'elektrik-ve-guvenli-kullanim';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Aşağıdakilerden hangisi yalıtkandır?', 'Bakır', 'Demir', 'Alüminyum', 'Plastik', 'd', 'Plastik elektriği iletmez, bu yüzden yalıtkandır.' FROM texts WHERE slug = 'elektrik-ve-guvenli-kullanim';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Elektrikli aletlere neden ıslak elle dokunmamalıyız?', 'Su elektriği ilettiği için', 'Aletler paslandığı için', 'Ellerimiz kayacağı için', 'Aletler kirlendiği için', 'a', 'Metinde su elektriği ilettiği için ıslak elle dokunmamamız gerektiği yazıyor.' FROM texts WHERE slug = 'elektrik-ve-guvenli-kullanim';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu metnin asıl amacı nedir?', 'Santrallerin tarihini anlatmak', 'Metallerin çeşitlerini saymak', 'Elektriğin ne olduğunu ve güvenli nasıl kullanılacağını açıklamak', 'Uçurtma yapmayı öğretmek', 'c', 'Metin önce elektriği tanıtıyor, sonra güvenlik kurallarını sıralıyor.' FROM texts WHERE slug = 'elektrik-ve-guvenli-kullanim';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('van-golu-ve-inci-kefali', 'Van Gölü ve İnci Kefalinin Yolculuğu', 'Doğu Anadolu''da, yüksek dağların arasında uçsuz bucaksız bir göl uzanır: Van Gölü. Türkiye''nin en büyük gölü olan Van Gölü, uzaktan bakıldığında bir denizi andırır. Suyunun rengi, havaya göre maviden turkuaza döner.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Van Gölü''nün suyu neden sıradan bir göl suyundan farklıdır?', 'İçinde çok miktarda soda bulunduğu için', 'Çok sıcak olduğu için', 'Tatlı su olduğu için', 'Hiç dalga olmadığı için', 'a', 'Metne göre gölün suyunda çok miktarda soda bulunur.' FROM texts WHERE slug = 'van-golu-ve-inci-kefali';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'İnci kefali göç ederken nereye gider?', 'Karadeniz''e', 'Gölün en derin yerine', 'Başka bir göle', 'Göle dökülen tatlı su derelerine', 'd', 'Balıklar yumurta bırakmak için göle dökülen derelere yüzer.' FROM texts WHERE slug = 'van-golu-ve-inci-kefali';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Göç döneminde avlanmak neden yasaktır?', 'Balıklar zehirli olduğu için', 'Balıkların neslini korumak için', 'Dereler donduğu için', 'Balıklar çok küçük olduğu için', 'b', 'Yasak, balıkların neslini korumak için konulmuştur.' FROM texts WHERE slug = 'van-golu-ve-inci-kefali';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metindeki ''havzaya özgü'' ifadesi ne anlama gelir?', 'Her yerde yaşayan', 'Yalnızca denizde yaşayan', 'Doğal olarak yalnızca o bölgede yaşayan', 'Başka yerden getirilmiş olan', 'c', 'Metin bunu ''dünyada başka hiçbir yerde doğal olarak yaşamaz'' diye açıklıyor.' FROM texts WHERE slug = 'van-golu-ve-inci-kefali';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('ormanda-pusulayla-yon-bulma', 'Ormanda Pusulayla Yön Bulma', 'İzci kampının üçüncü günüydü. Eğitmen Murat Bey, çocukları dörder kişilik gruplara ayırdı ve her gruba bir pusula ile basit bir harita verdi. ''Göreviniz, ormanın içindeki eski çeşmeyi bulup kampa geri dönmek,'' dedi.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Pusula ibresinin kırmızı ucu hangi yönü gösterir?', 'Güney', 'Kuzey', 'Doğu', 'Batı', 'b', 'Ayşe, kırmızı ucun her zaman kuzeyi gösterdiğini hatırlattı.' FROM texts WHERE slug = 'ormanda-pusulayla-yon-bulma';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Çeşme kampın hangi yönündeydi?', 'Güneybatısında', 'Batısında', 'Güneyinde', 'Kuzeydoğusunda', 'd', 'Haritaya göre çeşme kampın kuzeydoğusundaydı.' FROM texts WHERE slug = 'ormanda-pusulayla-yon-bulma';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kerem çam ağacını neden haritada işaretledi?', 'Dönüşte yol göstermesi için', 'Ağacı kesmek için', 'Ağaca tırmanmak için', 'Gölgesinde dinlenmek için', 'a', 'Kerem, ağacın dönüşte yol göstereceğini söyledi.' FROM texts WHERE slug = 'ormanda-pusulayla-yon-bulma';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Melis sağdaki yolu neden seçmedi?', 'Yol çok dikti', 'Yolda bir hayvan vardı', 'Yol güneye kıvrılıyordu', 'Yol çok karanlıktı', 'c', 'Melis pusulaya bakıp sağ yolun güneye kıvrıldığını fark etti.' FROM texts WHERE slug = 'ormanda-pusulayla-yon-bulma';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu hikâyeden hangi sonuç çıkarılabilir?', 'En kolay yol her zaman doğrudur', 'Ormana hiç girilmemelidir', 'En hızlı koşan grup her zaman kazanır', 'Pusula ve harita doğru kullanılırsa yolumuzu bulabiliriz', 'd', 'Grup, pusulayı ve haritayı dikkatle kullandığı için kaybolmadı.' FROM texts WHERE slug = 'ormanda-pusulayla-yon-bulma';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('sahra-colu', 'Kum Denizi: Sahra Çölü', 'Afrika''nın kuzeyinde, gözün alabildiğine uzanan dev bir çöl vardır: Sahra. Sahra, dünyanın en büyük sıcak çölüdür. Yüzölçümü yaklaşık dokuz milyon kilometrekaredir; bu, Türkiye''nin on bir katından fazladır. Sahra adı, Arapçada çöl anlamına gelen bir sözcükten gelir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Sahra''nın ne kadarı kum tepeleriyle kaplıdır?', 'Dörtte biri', 'Tamamı', 'Yarısı', 'Hiçbir yeri', 'a', 'Metne göre Sahra''nın yalnızca dörtte biri kum tepeleriyle kaplıdır.' FROM texts WHERE slug = 'sahra-colu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Sahra''da geceleri hava neden hızla soğur?', 'Rüzgâr kuzeyden estiği için', 'Bulut olmadığı için ısı uzaya kaçtığı için', 'Geceleri yağmur yağdığı için', 'Kum her zaman soğuk olduğu için', 'b', 'Bulut olmadığından gündüz biriken ısı gece kaçar.' FROM texts WHERE slug = 'sahra-colu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Vahalar nasıl oluşur?', 'Yer altı suyunun yüzeye çıkmasıyla', 'Deniz suyunun çöle taşmasıyla', 'İnsanların havuz kazmasıyla', 'Kar erimesiyle', 'a', 'Metinde vahaların, yer altı suyunun yüzeye çıktığı yerlerde oluştuğu yazıyor.' FROM texts WHERE slug = 'sahra-colu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Sahra''nın eskiden yeşil olduğunu nereden biliyoruz?', 'Develerin davranışlarından', 'Kayalara çizilmiş eski resimlerden', 'Kum tepelerinin renginden', 'Hurma ağaçlarının yaşından', 'b', 'O dönemde yaşayan insanlar kayalara zürafa ve fil resimleri çizmiştir.' FROM texts WHERE slug = 'sahra-colu';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('kara-delikler', 'Kara Delikler', 'Evrende en çok merak edilen gök cisimlerinden biri kara deliklerdir. Adları biraz korkutucu gelse de kara delikler, doğanın kurallarına uyan ve bilim insanlarının yıllardır incelediği ilginç yapılardır.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kara delikten neden ışık bile kaçamaz?', 'Kara delik çok soğuk olduğu için', 'Işık çok yavaş olduğu için', 'Kütleçekimi çok güçlü olduğu için', 'Kara delik çok uzakta olduğu için', 'c', 'Kara deliğin çekimi o kadar güçlüdür ki belirli bir sınırı geçen ışık bile kaçamaz.' FROM texts WHERE slug = 'kara-delikler';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kara delikler nasıl oluşur?', 'İki gezegen çarpışınca', 'Güneş battığında', 'Kuyruklu yıldızlar birleşince', 'Çok büyük yıldızların çekirdeği çökünce', 'd', 'Ömrünü tamamlayan çok büyük bir yıldızın çekirdeği çökerek kara delik oluşturur.' FROM texts WHERE slug = 'kara-delikler';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bilim insanları kara delikleri nasıl fark eder?', 'Çevresindeki yıldız ve gazların hareketlerini izleyerek', 'Kara deliğe uzay aracı göndererek', 'Kara deliğin sesini dinleyerek', 'Kara deliğin rengini ölçerek', 'a', 'Kara delikler görünmez, ama çevrelerindeki yıldız ve gazların hareketi onları ele verir.' FROM texts WHERE slug = 'kara-delikler';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Samanyolu''nun merkezindeki kara delik Dünya''yı neden tehdit etmez?', 'Çok küçük olduğu için', 'Çok uzakta olduğu için', 'Hareket etmediği için', 'Işık saçtığı için', 'b', 'Metne göre bu kara delik Dünya''dan çok uzaktadır.' FROM texts WHERE slug = 'kara-delikler';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metnin ana düşüncesi hangisidir?', 'Kara delikler Dünya için büyük bir tehlikedir', 'Işık evrendeki en yavaş şeydir', 'Kara delikler, çok güçlü çekimi olan ve bilimin incelediği ilginç gök cisimleridir', 'Kara deliklerin hiç görüntüsü elde edilmemiştir', 'c', 'Metin kara deliklerin ne olduğunu, nasıl oluştuğunu ve nasıl incelendiğini anlatır.' FROM texts WHERE slug = 'kara-delikler';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('depremler-neden-olur', 'Depremler Neden Olur, Ne Yapmalıyız?', 'Üzerinde yaşadığımız Dünya, dışarıdan bakınca sağlam ve hareketsiz görünür. Oysa yerin derinliklerinde sürekli ve çok yavaş bir hareket vardır. Depremleri anlamak için bu gizli hareketi tanımamız gerekir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yer kabuğunu oluşturan dev parçalara ne ad verilir?', 'Katman', 'Çekirdek', 'Kaya', 'Levha', 'd', 'Metne göre yer kabuğu levha adı verilen parçalardan oluşur.' FROM texts WHERE slug = 'depremler-neden-olur';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Depremin nedeni nedir?', 'Yer kabuğunda biriken enerjinin aniden boşalması', 'Güçlü rüzgârların esmesi', 'Denizlerin kabarması', 'Yağmurun toprağı yumuşatması', 'a', 'Levhalar takılınca biriken enerji bir anda boşalır ve yer sarsılır.' FROM texts WHERE slug = 'depremler-neden-olur';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metindeki cetvel örneği neyi anlatmak için verilmiştir?', 'Levhaların ne kadar büyük olduğunu', 'Enerjinin birikip aniden boşalmasını', 'Binaların nasıl yapıldığını', 'Levhaların ne kadar yavaş kaydığını', 'b', 'Bükülen cetvelin aniden eski hâline dönmesi, biriken enerjinin boşalmasına benzer.' FROM texts WHERE slug = 'depremler-neden-olur';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Deprem sırasında ne yapmalıyız?', 'Hemen merdivenlerden koşmalıyız', 'Pencerenin önünde beklemeliyiz', 'Çök, Kapan, Tutun hareketini yapmalıyız', 'Asansöre binmeliyiz', 'c', 'Metinde sarsıntı sırasında Çök, Kapan, Tutun hareketinin yapılması öğütleniyor.' FROM texts WHERE slug = 'depremler-neden-olur';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre bizi güvende tutan en önemli adım nedir?', 'Depremi önceden tahmin etmek', 'Hiç evden çıkmamak', 'Çok korkmak', 'Hazırlıklı olmak', 'd', 'Metinde ''Hazırlıklı olmak, bizi güvende tutan en önemli adımdır.'' deniyor.' FROM texts WHERE slug = 'depremler-neden-olur';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('gps-nasil-calisir', 'GPS Nasıl Çalışır?', 'Telefondaki haritaya bakarken ekranda yanıp sönen mavi noktayı hiç merak ettin mi? O nokta, tam olarak nerede olduğunu gösterir. Bu bilgiyi telefonuna veren sistemin adı GPS''tir. GPS, İngilizcede Küresel Konumlama Sistemi anlamına gelen sözcüklerin baş harflerinden oluşur.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'GPS uyduları Dünya''nın yaklaşık ne kadar yukarısındadır?', 'Yirmi bin kilometre', 'İki yüz kilometre', 'Bir milyon kilometre', 'İki kilometre', 'a', 'Metne göre uydular yaklaşık yirmi bin kilometre yukarıda dolaşır.' FROM texts WHERE slug = 'gps-nasil-calisir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Her GPS uydusunun içinde ne vardır?', 'Büyük bir teleskop', 'Çok hassas bir atom saati', 'Hava durumu ölçer', 'Bir pusula', 'b', 'Metinde her uydunun içinde son derece hassas bir atom saati olduğu yazıyor.' FROM texts WHERE slug = 'gps-nasil-calisir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'GPS alıcısı uyduya olan uzaklığı nasıl hesaplar?', 'Uydunun rengine bakarak', 'Uydunun fotoğrafını çekerek', 'Sinyalin çıkış ve varış anları arasındaki farktan', 'Rüzgârın hızını ölçerek', 'c', 'Alıcı, sinyalin yolda geçirdiği süreden uzaklığı bulur.' FROM texts WHERE slug = 'gps-nasil-calisir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Dördüncü uydunun görevi nedir?', 'Hava durumunu bildirmek', 'Fotoğraf çekmek', 'Telefonları şarj etmek', 'Saatlerdeki küçük farkları düzelterek sonucu kesinleştirmek', 'd', 'Üç uydu konumu bulur, dördüncüsü saat farklarını düzeltir.' FROM texts WHERE slug = 'gps-nasil-calisir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Aşağıdakilerden hangisi GPS kullanımına örnek değildir?', 'Ambulansın en kısa yolu bulması', 'Bir kitabın sayfalarını çevirmek', 'Geminin rotasını izlemesi', 'Traktörün tarlada düzgün sürülmesi', 'b', 'Kitap sayfası çevirmek konum bilgisi gerektirmez.' FROM texts WHERE slug = 'gps-nasil-calisir';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('ipek-yolu-ve-kervanlar', 'İpek Yolu ve Kervanlar', 'Bundan yaklaşık iki bin yıl önce, Çin''den Akdeniz kıyılarına kadar uzanan dev bir ticaret ağı oluştu. Bu yolların üzerinden taşınan en değerli mallardan biri ipek olduğu için, bu ağa çok sonraları İpek Yolu adı verildi. Aslında İpek Yolu tek bir yol değil, çöllerden, dağlardan ve bozkırlardan geçen pek çok yolun birleşmesiydi.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu ticaret ağına neden İpek Yolu adı verildi?', 'En değerli mallardan biri ipek olduğu için', 'Yollar ipekle kaplı olduğu için', 'İpek adında bir hükümdar kurduğu için', 'Yol ipek gibi düz olduğu için', 'a', 'Yol boyunca taşınan en değerli mallardan biri ipekti.' FROM texts WHERE slug = 'ipek-yolu-ve-kervanlar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kervanlarda neden çoğunlukla deve kullanılırdı?', 'Çok hızlı koştukları için', 'Ucuz oldukları için', 'Sıcağa ve susuzluğa dayanıklı oldukları için', 'Yüzebildikleri için', 'c', 'Metne göre develer sıcağa ve susuzluğa dayanıklıdır.' FROM texts WHERE slug = 'ipek-yolu-ve-kervanlar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kervansaraylar ne işe yarardı?', 'Savaşlarda kale olarak kullanılırdı', 'İçlerinde ipek üretilirdi', 'Okul olarak kullanılırdı', 'Yolcular konaklar, hayvanlar beslenir, mallar saklanırdı', 'd', 'Kervansaraylar yolcuların konaklaması için yapılmıştı.' FROM texts WHERE slug = 'ipek-yolu-ve-kervanlar';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre İpek Yolu''nun en önemli mirası nedir?', 'Develer', 'Kervansarayların sayısı', 'Düşüncelerin ve buluşların yayılması', 'İpeğin fiyatı', 'c', 'Metinde en önemli mirasın mallardan çok düşünceler olduğu belirtiliyor.' FROM texts WHERE slug = 'ipek-yolu-ve-kervanlar';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('ulug-bey-ve-semerkant-rasathanesi', 'Uluğ Bey ve Semerkant Rasathanesi', 'On beşinci yüzyılın başlarında Orta Asya''nın en parlak şehirlerinden biri Semerkant''tı. Mavi kubbeli yapıları, medreseleri ve kalabalık çarşılarıyla bu şehir, bilim insanlarının da buluşma noktasıydı. Bu canlılığın arkasında, Timur''un torunu olan Uluğ Bey vardı.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Uluğ Bey kimin torunudur?', 'Timur''un', 'Fatih Sultan Mehmet''in', 'Cengiz Han''ın', 'Ali Kuşçu''nun', 'a', 'Metinde Uluğ Bey''in Timur''un torunu olduğu yazıyor.' FROM texts WHERE slug = 'ulug-bey-ve-semerkant-rasathanesi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Rasathanedeki ölçüm aleti neden çok büyük yapılmıştı?', 'Şehrin her yerinden görünsün diye', 'Teleskop olmadığı için ölçümlerin doğruluğu aletin büyüklüğüne bağlıydı', 'Taş çok ucuz olduğu için', 'Hükümdar yalnızca büyük yapıları sevdiği için', 'b', 'Teleskobun olmadığı dönemde büyük aletler daha hassas ölçüm sağlıyordu.' FROM texts WHERE slug = 'ulug-bey-ve-semerkant-rasathanesi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Uluğ Bey ve ekibi aşağıdakilerden hangisini hazırladı?', 'Bir dünya haritası', 'Bir sözlük', 'Bir tarih kitabı', 'Bini aşkın yıldızın yer aldığı bir katalog', 'd', 'Ekip bini aşkın yıldızın konumunu içeren bir katalog hazırladı.' FROM texts WHERE slug = 'ulug-bey-ve-semerkant-rasathanesi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Rasathane yıkıldığı hâlde ekibin bilgisi nasıl kaybolmadı?', 'Rasathane kısa sürede yeniden yapıldığı için', 'Ali Kuşçu bu birikimi İstanbul''a taşıdığı için', 'Arkeolog bütün kitapları bulduğu için', 'Uluğ Bey çok uzun yaşadığı için', 'b', 'Ali Kuşçu İstanbul''a gelerek bilgiyi Osmanlı medreselerine taşıdı.' FROM texts WHERE slug = 'ulug-bey-ve-semerkant-rasathanesi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metnin ana fikri hangisidir?', 'Hükümdarlar bilimle hiç ilgilenmez', 'Büyük yapılar sonsuza kadar ayakta kalır', 'Merak ve bilgi, güç ve servetten daha kalıcı bir miras bırakabilir', 'Teleskop Semerkant''ta icat edilmiştir', 'c', 'Metnin son cümlesi bu düşünceyi açıkça dile getirir.' FROM texts WHERE slug = 'ulug-bey-ve-semerkant-rasathanesi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('macellanin-dunya-turu', 'Macellan''ın Dünya Turu Seferi', 'Beş yüz yıl kadar önce Avrupalı denizciler, değerli baharatların yetiştiği Baharat Adaları''na, yani bugünkü Endonezya''daki Maluku Adaları''na ulaşmanın yeni yollarını arıyordu. Portekizli denizci Ferdinand Macellan, bu adalara Afrika''yı dolaşmak yerine batıya doğru yelken açarak ulaşılabileceğine inanıyordu. Kendi ülkesinden destek bulamayınca planını İspanya kralına sundu ve kabul gördü.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Macellan hangi ülkenin desteğiyle yola çıktı?', 'İspanya', 'Portekiz', 'İngiltere', 'Fransa', 'a', 'Portekiz''den destek bulamayınca İspanya kralının desteğini aldı.' FROM texts WHERE slug = 'macellanin-dunya-turu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Pasifik adı ne anlama gelir?', 'Fırtınalı', 'Derin', 'Soğuk', 'Sakin, barışçıl', 'd', 'Macellan durgun okyanusa sakin, barışçıl anlamına gelen Pasifik adını verdi.' FROM texts WHERE slug = 'macellanin-dunya-turu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Pasifik geçişinde denizciler neden hastalandı?', 'Soğuktan dondukları için', 'Taze meyve ve sebze eksikliği yüzünden', 'Fırtınada yaralandıkları için', 'Gemiler battığı için', 'b', 'Metinde taze meyve ve sebze eksikliği yüzünden hastalandıkları yazıyor.' FROM texts WHERE slug = 'macellanin-dunya-turu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yolculuğu tamamlayıp İspanya''ya dönen gemi hangisidir?', 'Victoria', 'Trinidad', 'Santa Maria', 'Pasifik', 'a', '1522''de yalnızca Victoria gemisi on sekiz kişiyle döndü.' FROM texts WHERE slug = 'macellanin-dunya-turu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu seferin en önemli sonucu nedir?', 'Macellan''ın çok zengin olması', 'Baharatların ucuzlaması', 'Macellan''ın Filipinler''e yerleşmesi', 'Dünyanın çevresinin gemiyle dolaşılabileceğinin ve okyanusların bağlı olduğunun gösterilmesi', 'd', 'Sefer, gemiyle dünyanın çevresinin dolaşılabildiğini ve okyanusların birbirine bağlı olduğunu gösterdi.' FROM texts WHERE slug = 'macellanin-dunya-turu';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('kar-taneleri', 'Kar Taneleri', 'Kış geldi. Gökyüzünden beyaz kar taneleri düşüyor. Ela pencereden bakıyor. Eldivenine bir kar tanesi konuyor. Hemen büyüteçle yakından bakıyor.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ela''nın gördüğü kar tanesinin kaç kolu vardı?', 'Dört', 'Beş', 'Altı', 'Sekiz', 'c', 'Metinde "Kar tanesinin altı kolu var." deniyor.' FROM texts WHERE slug = 'kar-taneleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kar taneleri nerede oluşur?', 'Bulutlarda', 'Denizde', 'Toprağın altında', 'Ağaçların üstünde', 'a', 'Kar taneleri bulutlarda, su buharı donunca oluşur.' FROM texts WHERE slug = 'kar-taneleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kar taneleri neden yavaş yavaş iner?', 'Çok ağır oldukları için', 'Rüzgâr hiç esmediği için', 'Güneş onları tuttuğu için', 'Çok hafif oldukları için', 'd', 'Metinde kar tanelerinin çok hafif olduğu için süzülerek indiği yazıyor.' FROM texts WHERE slug = 'kar-taneleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu metin en çok neyi anlatıyor?', 'Ela''nın okuluna nasıl gittiğini', 'Kar tanelerinin nasıl oluştuğunu ve şekillerini', 'Büyüteç nasıl yapılır', 'Kış tatilinde yapılan geziyi', 'b', 'Metnin büyük kısmı kar tanelerinin oluşumunu ve şekillerini anlatıyor.' FROM texts WHERE slug = 'kar-taneleri';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('balkonda-domates', 'Balkonda Domates', 'Mert''in evinin küçük bir balkonu var. Bir gün annesi eve bir torba toprak ve bir paket tohum getiriyor. "Hadi, balkonda domates yetiştirelim!" diyor.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Mert ile annesi saksıyı nereye koydu?', 'Karanlık bir dolaba', 'Güneş alan köşeye', 'Buzdolabının yanına', 'Kapının arkasına', 'b', 'Domates güneşi sevdiği için saksı güneş alan köşeye kondu.' FROM texts WHERE slug = 'balkonda-domates';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Mert neden çok fazla su vermiyor?', 'Su bittiği için', 'Annesi kızdığı için', 'Domates suyu sevmediği için', 'Fazla su köklere zarar verdiği için', 'd', 'Metinde fazla suyun köklere zarar verdiği yazıyor.' FROM texts WHERE slug = 'balkonda-domates';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Küçük domatesler hangi şeylerin yerinde belirdi?', 'Sarı çiçeklerin', 'Yaprakların', 'Çubukların', 'Köklerin', 'a', 'Sarı çiçekler açtı, onların yerinde domatesler belirdi.' FROM texts WHERE slug = 'balkonda-domates';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Mert bu olaydan ne öğrenmiş olabilir?', 'Domatesler bir günde olgunlaşır.', 'Bitkiler güneş istemez.', 'Bitki yetiştirmek sabır ve özen ister.', 'Tohumlar suya gerek duymaz.', 'c', 'Mert haftalarca bitkiye baktı; bu, sabır ve özen gerektiğini gösterir.' FROM texts WHERE slug = 'balkonda-domates';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('yaya-gecidinde-dikkat', 'Yaya Geçidinde Dikkat', 'Zeynep ile dedesi her sabah birlikte okula yürür. Okulun önünde geniş bir cadde vardır. Caddede arabalar hızlı geçer.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Dedeye göre yayalar nerede yürümelidir?', 'Yolun ortasında', 'Arabaların arasında', 'Bisiklet yolunda', 'Kaldırımda', 'd', 'Dede, "Kaldırım yayalar içindir." diyor.' FROM texts WHERE slug = 'yaya-gecidinde-dikkat';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yayalar için kırmızı ışık yanınca ne yapılmalıdır?', 'Koşarak geçilmelidir', 'Beklenmelidir', 'Telefonla oynanmalıdır', 'Geri dönülmelidir', 'b', 'Metinde kırmızı ışıkta beklemek gerektiği yazıyor.' FROM texts WHERE slug = 'yaya-gecidinde-dikkat';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yeşil ışık yandığında dede Zeynep''e ne söyledi?', 'Hemen koşmasını', 'Gözlerini kapatmasını', 'Önce sola, sonra sağa, sonra yine sola bakmasını', 'Telefonuna bakmasını', 'c', 'Dede geçmeden önce iki yana bakmayı hatırlattı.' FROM texts WHERE slug = 'yaya-gecidinde-dikkat';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Zeynep neden "Yarın kuralları ben sana söyleyeyim mi?" dedi?', 'Trafik kurallarını öğrendiği için', 'Okula gitmek istemediği için', 'Dedesi kuralları unuttuğu için', 'Işıklar bozulduğu için', 'a', 'Zeynep kuralları öğrendi ve bunu göstermek istiyor.' FROM texts WHERE slug = 'yaya-gecidinde-dikkat';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('ruzgarin-goturdugu-ucurtma', 'Rüzgârın Götürdüğü Uçurtma', 'Cumartesi günü Can ve kız kardeşi Ada tepeye çıkıyor. Ellerinde kırmızı bir uçurtma var. Uçurtmayı babalarıyla birlikte yapmışlardı.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Çocukların uçurtması ne renkti?', 'Kırmızı', 'Mavi', 'Sarı', 'Yeşil', 'a', 'Metinde kırmızı bir uçurtma olduğu yazıyor.' FROM texts WHERE slug = 'ruzgarin-goturdugu-ucurtma';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Uçurtma nereye takıldı?', 'Bir evin çatısına', 'Bir elektrik direğine', 'Bir ağacın dalına', 'Bir çitin üstüne', 'c', 'Uçurtma çiftlikteki küçük bir ağacın dalına takıldı.' FROM texts WHERE slug = 'ruzgarin-goturdugu-ucurtma';
