INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('flamingolar-ve-gediz-deltasi', 'Flamingolar ve Gediz Deltası', 'İzmir''in hemen yanında, Gediz Nehri''nin denize kavuştuğu yerde geniş bir sulak alan vardır. Burası Gediz Deltası''dır. Deltada tuzlu göller, sazlıklar ve sığ sular bulunur. Bu alan, yüzlerce kuş türüne ev sahipliği yapar. En dikkat çekici olanlar ise pembe tüylü flamingolardır.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Gediz Deltası hangi ilimizin yakınındadır?', 'Ankara', 'Trabzon', 'İzmir', 'Erzurum', 'c', 'Metin, deltanın İzmir''in hemen yanında olduğunu söylüyor.' FROM texts WHERE slug = 'flamingolar-ve-gediz-deltasi';
