INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Flamingoların tüyleri neden pembeleşir?', 'Güneşte yandıkları için', 'Tuzlu suda yıkandıkları için', 'Anneleri onları boyadığı için', 'Yedikleri besinlerdeki doğal boyalar yüzünden', 'd', 'Minik karides ve yosunlardaki doğal boyalar tüyleri pembeye boyar.' FROM texts WHERE slug = 'flamingolar-ve-gediz-deltasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Gediz Deltası kirlenirse ne olabilir?', 'Flamingolar daha pembe olur.', 'Flamingolar ve diğer kuşlar zarar görür.', 'Kuş sayısı hemen artar.', 'Hiçbir şey değişmez.', 'b', 'Metin, kuşların yaşaması için deltanın temiz kalması gerektiğini vurguluyor.' FROM texts WHERE slug = 'flamingolar-ve-gediz-deltasi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('fillerin-hafizasi', 'Fillerin Hafızası', 'Filler karada yaşayan en büyük hayvanlardır. Ama onları özel yapan tek şey büyüklükleri değildir. Fillerin çok güçlü bir hafızası ve birbirine sıkı sıkıya bağlı aileleri vardır.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bir fil sürüsünü genellikle kim yönetir?', 'En genç erkek fil', 'En yaşlı dişi fil', 'En küçük yavru', 'En hızlı koşan fil', 'b', 'Metinde sürüyü genellikle en yaşlı dişi filin yönettiği yazıyor.' FROM texts WHERE slug = 'fillerin-hafizasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Lider anne kurak mevsimde neyi hatırlar?', 'Yavruların isimlerini', 'Yağmurun ne zaman yağacağını', 'Rüzgârın yönünü', 'Suyun nerede bulunduğunu', 'd', 'Lider anne kurak mevsimde su kaynaklarının yerini hatırlar.' FROM texts WHERE slug = 'fillerin-hafizasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Erkek filler büyüyünce genellikle ne yapar?', 'Sürüden ayrılır', 'Sürünün lideri olur', 'Yavrulara bakar', 'Sürünün önünde yürür', 'a', 'Metinde erkek fillerin büyüyünce genellikle sürüden ayrıldığı yazıyor.' FROM texts WHERE slug = 'fillerin-hafizasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu metnin ana fikri nedir?', 'Filler en hızlı koşan hayvanlardır.', 'Filler yalnız yaşamayı sever.', 'Fillerin güçlü bir hafızası ve sıkı aile bağları vardır.', 'Fillerin hortumu yalnızca su içmeye yarar.', 'c', 'Metin boyunca fillerin hafızası ve aile yaşamı anlatılıyor.' FROM texts WHERE slug = 'fillerin-hafizasi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('muzede-hazine-avi', 'Müzede Hazine Avı', 'Okulun müze gezisi günüydü. Rehber Selin Hanım çocukları müzenin girişinde topladı. Elinde renkli kartlar vardı. "Bugün müzede bir hazine avı yapacağız," dedi. "Her kartta bir ipucu var. İpuçlarını çözen grup, gizli hazineyi bulacak." Sonra önemli bir kuralı hatırlattı: "Müzede koşmak, bağırmak ve eserlere dokunmak yasaktır. Eserler çok eskidir ve kolayca zarar görebilir."
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'İlk ipucunun cevabı neydi?', 'Heykel', 'Kılıç', 'Harita', 'Küp', 'd', 'Topraktan yapılan ve zeytinyağı taşıyan eşya küptür.' FROM texts WHERE slug = 'muzede-hazine-avi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Deniz neden sesini alçalttı?', 'Boğazı ağrıdığı için', 'Müzede bağırmaması gerektiğini hatırladığı için', 'Rehber onu azarladığı için', 'Yanlış cevap verdiği için', 'b', 'Metinde Deniz''in müzede bağırmaması gerektiğini hatırladığı yazıyor.' FROM texts WHERE slug = 'muzede-hazine-avi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Hazine kutusu nerede bulundu?', 'Seramik bölümünde', 'Müzenin bahçesinde', 'Müzenin kütüphanesinde', 'Girişteki masada', 'c', 'Elif kutuyu kütüphanedeki rafların arasında gördü.' FROM texts WHERE slug = 'muzede-hazine-avi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Nottaki söze göre asıl hazine nedir?', 'Merak etmek ve öğrenmek', 'Altın ve mücevher', 'Eski paralar', 'Yarışmayı kazanmak', 'a', 'Notta "Asıl hazine, merak etmek ve öğrenmektir." yazıyordu.' FROM texts WHERE slug = 'muzede-hazine-avi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('buyuk-ayi-takimyildizi', 'Büyük Ayı Takımyıldızı', 'Bulutsuz bir gecede gökyüzüne baktığınızda sayısız yıldız görürsünüz. Eski çağlardaki insanlar bu yıldızları birbirine bağlayarak hayali şekiller çizmişlerdir. Bu yıldız gruplarına takımyıldız denir. Bugün gökbilimciler gökyüzünü 88 takımyıldıza ayırır.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Gökbilimciler bugün gökyüzünü kaç takımyıldıza ayırır?', '88', '7', '12', '100', 'a', 'Metinde gökyüzünün 88 takımyıldıza ayrıldığı yazıyor.' FROM texts WHERE slug = 'buyuk-ayi-takimyildizi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Büyük Kepçe kaç yıldızdan oluşur?', 'Üç', 'Dört', 'Yedi', 'On', 'c', 'Büyük Ayı''nın en parlak yedi yıldızı kepçe şeklini oluşturur.' FROM texts WHERE slug = 'buyuk-ayi-takimyildizi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kutup Yıldızı bize hangi yönü gösterir?', 'Güneyi', 'Kuzeyi', 'Doğuyu', 'Batıyı', 'b', 'Metinde Kutup Yıldızı''nın kuzeyi gösterdiği yazıyor.' FROM texts WHERE slug = 'buyuk-ayi-takimyildizi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Pusulası olmayan bir denizci geceleyin yolunu nasıl bulabilir?', 'Ay''ın rengine bakarak', 'Dalgaların sesini dinleyerek', 'Bulutları sayarak', 'Büyük Kepçe yardımıyla Kutup Yıldızı''nı bularak', 'd', 'Büyük Kepçe Kutup Yıldızı''nı, Kutup Yıldızı da kuzeyi gösterir.' FROM texts WHERE slug = 'buyuk-ayi-takimyildizi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('ormanlar-ve-oksijen', 'Ormanlar ve Oksijen', 'Ormanda yürürken derin bir nefes aldığınızda kendinizi ferah hissedersiniz. Bunun nedenlerinden biri, ağaçların havayı temizlemesidir. Peki ağaçlar bunu nasıl yapar?
