INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ağaçların kökleri ne işe yarar?', 'Yağmuru durdurur', 'Havayı ısıtır', 'Hayvanları uzaklaştırır', 'Toprağı tutar', 'd', 'Kökler toprağı tutar ve sel sularıyla taşınmasını engeller.' FROM texts WHERE slug = 'ormanlar-ve-oksijen';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ormana pikniğe giden bir aile ne yapmalıdır?', 'Çöplerini ağaç diplerine bırakmalıdır.', 'Ateş yakmamalı ve çöplerini yanına almalıdır.', 'Ağaç dallarını kırmalıdır.', 'Büyük bir ateş yakmalıdır.', 'b', 'Metin ormanları korumak için ateş yakmamayı ve çöpleri geri götürmeyi öneriyor.' FROM texts WHERE slug = 'ormanlar-ve-oksijen';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('gunes-ve-ay-tutulmalari', 'Güneş ve Ay Tutulmaları', 'Güneş, Dünya ve Ay uzayda sürekli hareket eder. Dünya Güneş''in etrafında, Ay da Dünya''nın etrafında döner. Bazen bu üç gök cismi tam olarak aynı hizaya gelir. İşte o zaman gökyüzünde tutulma denen ilginç bir olay yaşanır.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Güneş tutulmasında hangi gök cismi Güneş ile Dünya''nın arasına girer?', 'Mars', 'Ay', 'Bir kuyruklu yıldız', 'Kutup Yıldızı', 'b', 'Güneş tutulmasında Ay, Güneş ile Dünya''nın arasına girer.' FROM texts WHERE slug = 'gunes-ve-ay-tutulmalari';
