INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ay tutulması hangi zamanda görülebilir?', 'Yalnızca dolunayda', 'Yalnızca öğle vakti', 'Her gece', 'Yalnızca kışın', 'a', 'Metin, ay tutulmasının yalnızca dolunay zamanında görülebileceğini söylüyor.' FROM texts WHERE slug = 'gunes-ve-ay-tutulmalari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Eski çağlarda insanlar tutulmalardan neden korkarlardı?', 'Tutulmalar çok gürültülü olduğu için', 'Tutulmalar her gün olduğu için', 'Tutulmaların nedenini bilmedikleri için', 'Gökbilimciler onları korkuttuğu için', 'c', 'Metinde insanların tutulmaların nedenini bilmedikleri için korktuğu yazıyor.' FROM texts WHERE slug = 'gunes-ve-ay-tutulmalari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Güneş tutulmasını izlerken hangisi doğru bir davranıştır?', 'Çıplak gözle bakmak', 'Normal güneş gözlüğü takmak', 'Dürbünle doğrudan bakmak', 'Özel tutulma gözlüğü kullanmak', 'd', 'Güneş''e çıplak gözle ya da normal gözlükle bakmak gözlere kalıcı zarar verebilir.' FROM texts WHERE slug = 'gunes-ve-ay-tutulmalari';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('uyku-ve-beynimiz', 'Uyku ve Beynimiz', 'Her gece yatağa girip gözlerimizi kapattığımızda vücudumuz dinlenmeye başlar. Ama beynimiz uyurken tamamen durmaz. Aksine, çok önemli işler yapmaya devam eder.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Uyku sırasında beyin gün içinde topladığı bilgilerle ne yapar?', 'Hepsini siler', 'Onları düzenler ve önemlilerini hafızaya yerleştirir', 'Hiçbir şey yapmaz', 'Onları rüyaya çevirip unutur', 'b', 'Metinde beynin uyurken bilgileri düzenlediği yazıyor.' FROM texts WHERE slug = 'uyku-ve-beynimiz';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Rüyaların çoğunu hangi aşamada görürüz?', 'Uyanık olduğumuz aşamada', 'Yemek yediğimiz sırada', 'Gözlerin hızla hareket ettiği aşamada', 'Uykuya dalmadan hemen önce', 'c', 'Metne göre rüyaların çoğu gözlerin hızla hareket ettiği aşamada görülür.' FROM texts WHERE slug = 'uyku-ve-beynimiz';
