INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ertesi gün sınavı olan bir öğrenci için en doğru davranış hangisidir?', 'Sabaha kadar uyumadan çalışmak', 'Gece geç saate kadar oyun oynamak', 'Konuları tekrar edip yeterince uyumak', 'Hiç uyumadan okula gitmek', 'c', 'Uyku, öğrenilenlerin hafızaya yerleşmesine yardım eder.' FROM texts WHERE slug = 'uyku-ve-beynimiz';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('kirkpinar-yagli-guresleri', 'Kırkpınar Yağlı Güreşleri', 'Her yaz Edirne''de, Sarayiçi denilen yeşil çayırda büyük bir heyecan yaşanır. Yüzlerce pehlivan, Kırkpınar Yağlı Güreşleri''nde yarışmak için buraya gelir. Kırkpınar''ın 1300''lü yıllardan beri düzenlendiği kabul edilir. Bu nedenle dünyanın en eski spor organizasyonlarından biri olarak bilinir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kırkpınar Yağlı Güreşleri hangi şehirde yapılır?', 'Konya', 'Edirne', 'Antalya', 'Kars', 'b', 'Metinde güreşlerin Edirne''de, Sarayiçi''nde yapıldığı yazıyor.' FROM texts WHERE slug = 'kirkpinar-yagli-guresleri';
