INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Cazgırın görevi nedir?', 'Davul çalmak', 'Pehlivanlara yağ sürmek', 'Pehlivanları manilerle seyircilere tanıtmak', 'Kemeri hazırlamak', 'c', 'Metinde cazgırın pehlivanları yüksek sesle, manilerle tanıttığı yazıyor.' FROM texts WHERE slug = 'kirkpinar-yagli-guresleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yağlı güreş neden hem güç hem de ustalık ister?', 'Yağlı bir rakibi tutmak çok zor olduğu için', 'Güreş çok kısa sürdüğü için', 'Pehlivanlar ayakkabı giydiği için', 'Güreş kum üzerinde yapıldığı için', 'a', 'Zeytinyağı sürülmüş bir rakibi kavramak zordur, bu da ustalık gerektirir.' FROM texts WHERE slug = 'kirkpinar-yagli-guresleri';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu metinden hangi sonuca ulaşılabilir?', 'Kırkpınar yeni başlamış bir yarışmadır.', 'Yağlı güreşte kurallar yoktur.', 'Kırkpınar''da yalnızca kazanmak önemlidir.', 'Kırkpınar, saygıya önem veren köklü bir gelenektir.', 'd', 'Metin hem uzun geçmişi hem de rakibe saygıyı vurguluyor.' FROM texts WHERE slug = 'kirkpinar-yagli-guresleri';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('gunes-panelleri-ve-temiz-enerji', 'Güneş Panelleri ve Temiz Enerji', 'Evlerin çatılarında, tarlalarda ya da sokak lambalarının üstünde koyu mavi veya siyah plakalar görmüşsünüzdür. Bunlar güneş panelleridir. Güneş panelleri, Güneş''ten gelen ışığı elektriğe dönüştürür.
