INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('selcuklu-kervansaraylari', 'Selçuklu Kervansarayları', 'Yaklaşık sekiz yüz yıl önce Anadolu''nun yollarında develer, atlar ve katırlardan oluşan uzun kervanlar yolculuk ederdi. Bu kervanlar ipek, baharat, halı ve değerli taşlar gibi malları bir şehirden diğerine taşırdı. Ancak yolculuk zor ve tehlikeliydi. Yollarda eşkıyalar, kötü hava ve vahşi hayvanlar yolculara zarar verebilirdi. Kervanların geceyi güvenle geçirebileceği yerlere ihtiyaç vardı.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kervansaraylar genellikle birbirinden ne kadar uzaklıktaydı?', 'Yaklaşık bir saatlik yol', 'Yaklaşık bir aylık yol', 'Yan yana', 'Yaklaşık bir günlük yol', 'd', 'Metinde kervansarayların yaklaşık bir günlük yol uzaklıkta olduğu yazıyor.' FROM texts WHERE slug = 'selcuklu-kervansaraylari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Taçkapı nedir?', 'Sultanın tacı', 'Kervansarayın süslü büyük giriş kapısı', 'Hayvanların kaldığı ahır', 'Kervanın başındaki deve', 'b', 'Taçkapı, taş işlemeleriyle süslenen büyük giriş kapısıdır.' FROM texts WHERE slug = 'selcuklu-kervansaraylari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Sultanhanı hangi ilimizdedir?', 'Bursa', 'Sinop', 'Aksaray', 'Van', 'c', 'Metinde Sultanhanı''nın Aksaray''da olduğu yazıyor.' FROM texts WHERE slug = 'selcuklu-kervansaraylari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yolcuların ücretsiz ağırlanmasının sonucu ne oldu?', 'Ticaret gelişti ve şehirler zenginleşti.', 'Kervanlar yolculuğu bıraktı.', 'Kervansaraylar kapandı.', 'Yollar daha tehlikeli oldu.', 'a', 'Ücretsiz konaklama tüccarları çekti; ticaret gelişti.' FROM texts WHERE slug = 'selcuklu-kervansaraylari';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Selçuklular kervansarayları en çok hangi amaçla yaptırmıştır?', 'Kervanların güvenle konaklayabilmesi için', 'Savaşta asker saklamak için', 'Yalnızca sultanların dinlenmesi için', 'Hayvan satmak için', 'a', 'Metin, kervanların geceyi güvenle geçirecek yerlere ihtiyaç duyduğunu anlatıyor.' FROM texts WHERE slug = 'selcuklu-kervansaraylari';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('dinozor-fosilleri-nasil-bulunur', 'Dinozor Fosilleri Nasıl Bulunur?', 'Dinozorlar, kuşların ataları dışında, yaklaşık 66 milyon yıl önce yeryüzünden silinip gitti. Hiçbir insan bir dinozoru canlı olarak görmedi. Peki, onların nasıl göründüğünü, ne yediğini ve ne kadar büyük olduğunu nereden biliyoruz? Bu soruların cevabı fosillerde saklıdır.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Fosil nedir?', 'Yeni bulunmuş bir hayvan türü', 'Dinozorların yediği bitkiler', 'Çok eski canlıların taşlaşmış kalıntıları ya da izleri', 'Müzelerde yapılan oyuncak heykeller', 'c', 'Metinde fosilin eski canlıların taşlaşmış kalıntıları ya da izleri olduğu yazıyor.' FROM texts WHERE slug = 'dinozor-fosilleri-nasil-bulunur';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Fosilleri inceleyen bilim insanlarına ne ad verilir?', 'Gökbilimci', 'Paleontolog', 'Meteorolog', 'Veteriner', 'b', 'Metinde fosilleri inceleyenlere paleontolog dendiği yazıyor.' FROM texts WHERE slug = 'dinozor-fosilleri-nasil-bulunur';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Gömülü kemikler zamanla nasıl yüzeye çıkar?', 'Dinozorlar onları kazdıkça', 'Güneş onları ısıttıkça', 'Kemikler kendi kendine yükseldikçe', 'Yağmur ve rüzgâr kayaları aşındırdıkça', 'd', 'Metne göre yağmur ve rüzgâr kayaları aşındırınca kemikler görünür hâle gelir.' FROM texts WHERE slug = 'dinozor-fosilleri-nasil-bulunur';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kırılgan kemikler taşınmadan önce neden alçılı bezlerle sarılır?', 'Daha güzel görünsünler diye', 'Daha hızlı kurusunlar diye', 'Yolda kırılmasınlar diye', 'Rengi değişsin diye', 'c', 'Alçı, tıpkı kırık bir kolda olduğu gibi kemikleri korur.' FROM texts WHERE slug = 'dinozor-fosilleri-nasil-bulunur';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu metnin ana fikri nedir?', 'Bilim insanları fosiller sayesinde dinozorlar hakkında bilgi edinir.', 'Dinozorlar bugün hâlâ yaşamaktadır.', 'Fosiller yalnızca çocuklar tarafından bulunur.', 'Dinozorların hepsi ot yiyordu.', 'a', 'Metin fosillerin nasıl oluştuğunu, bulunduğunu ve bize ne anlattığını açıklıyor.' FROM texts WHERE slug = 'dinozor-fosilleri-nasil-bulunur';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('olimpiyat-oyunlarinin-tarihi', 'Olimpiyat Oyunlarının Tarihi', 'Olimpiyat Oyunları, bugün dünyanın dört bir yanından sporcuları bir araya getiren en büyük spor etkinliğidir. Ancak bu oyunların hikâyesi yaklaşık üç bin yıl önce, Antik Yunan''da başlar.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kayıtlara geçen ilk Olimpiyat Oyunları nerede yapılmıştır?', 'Roma''da', 'Paris''te', 'İstanbul''da', 'Olimpiya''da', 'd', 'Metinde ilk oyunların Olimpiya adlı yerde düzenlendiği yazıyor.' FROM texts WHERE slug = 'olimpiyat-oyunlarinin-tarihi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Antik Olimpiyatlarda kazananlara ne verilirdi?', 'Altın madalya', 'Zeytin dalından bir taç', 'Bir kupa', 'Bir at', 'b', 'Kazananlara madalya değil, zeytin dalından taç verilirdi.' FROM texts WHERE slug = 'olimpiyat-oyunlarinin-tarihi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'İlk modern Olimpiyat Oyunları hangi yıl yapılmıştır?', '776', '1896', '1900', '1924', 'b', 'İlk modern oyunlar 1896''da Atina''da yapıldı.' FROM texts WHERE slug = 'olimpiyat-oyunlarinin-tarihi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Olimpiyat bayrağındaki beş halka neyi simgeler?', 'Beş farklı sporu', 'Beş kazanan sporcuyu', 'Oyunların beş gün sürdüğünü', 'Kıtaların birliğini ve dostluğunu', 'd', 'Metinde halkaların kıtaların birliğini ve dostluğunu simgelediği yazıyor.' FROM texts WHERE slug = 'olimpiyat-oyunlarinin-tarihi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Oyunlar sırasında savaşlara ara verilmesi neyi gösterir?', 'Olimpiyatların barışla ilişkilendirildiğini', 'Askerlerin spor yapmayı sevmediğini', 'Oyunların çok kısa sürdüğünü', 'Şehirlerin birbirini tanımadığını', 'a', 'Hem antik gelenek hem de Coubertin''in düşüncesi oyunların barışla bağını gösterir.' FROM texts WHERE slug = 'olimpiyat-oyunlarinin-tarihi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('nemrut-dagi', 'Nemrut Dağı', 'Adıyaman''da, yaklaşık 2.150 metre yüksekliğindeki Nemrut Dağı''nın zirvesine sabahın erken saatlerinde çıkan ziyaretçiler, karanlıkta sessizce beklerler. Güneş doğarken ilk ışıklar, dağın tepesindeki dev taş başları altın rengine boyar. Bu manzara, Türkiye''nin en etkileyici görüntülerinden biridir. Ancak zirveye ulaşmak kolay değildir. Ziyaretçiler araçla belli bir noktaya kadar gelir, sonra dik bir patikada yürür. Zirvede hava yazın bile serin olabilir; bu yüzden gün doğumunu izlemeye gelenler yanlarına kalın giysiler alır.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Nemrut Dağı hangi ilimizdedir?', 'Aksaray', 'Çorum', 'Adıyaman', 'Edirne', 'c', 'Metnin başında Nemrut Dağı''nın Adıyaman''da olduğu yazıyor.' FROM texts WHERE slug = 'nemrut-dagi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Nemrut Dağı''ndaki heykelleri hangi krallık yaptırmıştır?', 'Hitit Devleti', 'Selçuklu Devleti', 'Lidya Krallığı', 'Kommagene Krallığı', 'd', 'Metinde heykelleri Kommagene Krallığı''nın yaptırdığı yazıyor.' FROM texts WHERE slug = 'nemrut-dagi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Tümülüs nedir?', 'Heykellerin gövdesi', 'Taş parçaları yığılarak yapılan yapay tepe', 'Kralın tacı', 'Bir tür tapınak kapısı', 'b', 'Metinde küçük taşların yığılmasıyla oluşan yapay tepeye tümülüs dendiği açıklanıyor.' FROM texts WHERE slug = 'nemrut-dagi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Heykellerin başları neden yerdedir?', 'İşçiler onları yere koyduğu için', 'Başlar hiç takılmadığı için', 'Depremler ve zorlu hava koşulları yüzünden düştükleri için', 'Ziyaretçiler onları indirdiği için', 'c', 'Metne göre başlar depremler ve hava koşulları nedeniyle düşmüştür.' FROM texts WHERE slug = 'nemrut-dagi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Heykellerin hem doğu hem batı kültürlerinden izler taşıması neyi gösterir?', 'Kommagene''nin farklı kültürlerin buluştuğu bir yer olduğunu', 'Heykellerin yakın zamanda yapıldığını', 'Kommagene''nin çok büyük bir ülke olduğunu', 'Heykelleri başka ülkelerin getirdiğini', 'a', 'Metinde bu durumun farklı kültürlerin buluşmasını gösterdiği yazıyor.' FROM texts WHERE slug = 'nemrut-dagi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('yapay-zeka-nedir', 'Yapay Zekâ Nedir?', 'Telefona bir soru sorduğunuzda cevap veren sesli asistanları, çeviri uygulamalarını ya da size izleyeceğiniz çizgi filmleri öneren programları duymuşsunuzdur. Bunların birçoğunun arkasında yapay zekâ vardır. Peki yapay zekâ tam olarak nedir?
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre yapay zekâ nasıl öğrenir?', 'Çok sayıda örneği inceleyerek', 'Okula giderek', 'Rüya görerek', 'Hiç öğrenmez, her şeyi baştan bilir', 'a', 'Metinde yapay zekânın çok sayıda örneği inceleyerek öğrendiği yazıyor.' FROM texts WHERE slug = 'yapay-zeka-nedir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Aşağıdakilerden hangisi metne göre doğrudur?', 'Yapay zekâ bir insan beynine sahiptir.', 'Yapay zekâ hiç hata yapmaz.', 'Yapay zekâ bizim gibi hissetmez.', 'Yapay zekâ yalnızca oyun oynar.', 'c', 'Metin, yapay zekânın insan gibi hissetmediğini belirtiyor.' FROM texts WHERE slug = 'yapay-zeka-nedir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yapay zekâ neden yanlış cevaplar verebilir?', 'Yorulduğu için', 'Öğrendiği örnekler eksik ya da yanlış olabileceği için', 'Canı istemediği için', 'Elektrik kesildiği için', 'b', 'Metinde örnekler eksik ya da yanlışsa yanlış cevap verebileceği yazıyor.' FROM texts WHERE slug = 'yapay-zeka-nedir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yapay zekâ programlarıyla hangi bilgiler paylaşılmamalıdır?', 'Sevdiğimiz renk', 'Bir hayvanın adı', 'Bir matematik sorusu', 'Ad, adres ve şifre gibi kişisel bilgiler', 'd', 'Metin kişisel bilgilerin paylaşılmaması gerektiğini söylüyor.' FROM texts WHERE slug = 'yapay-zeka-nedir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bu metnin ana fikri nedir?', 'Yapay zekâ insanların yerini tamamen alacaktır.', 'Yapay zekâ çok tehlikelidir, hiç kullanılmamalıdır.', 'Yapay zekâ faydalı bir araçtır ama dikkatli kullanılmalıdır.', 'Yapay zekâ yalnızca kedi ve köpekleri tanır.', 'c', 'Metin hem faydaları hem de dikkat edilmesi gerekenleri dengeli biçimde anlatıyor.' FROM texts WHERE slug = 'yapay-zeka-nedir';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('hititler-ve-kades-antlasmasi', 'Hititler ve Kadeş Antlaşması', 'Bundan yaklaşık üç bin beş yüz yıl önce Anadolu''da güçlü bir uygarlık hüküm sürüyordu: Hititler. Başkentleri Hattuşa, bugünkü Çorum iline bağlı Boğazkale ilçesinin yakınlarındaydı. Kalın surlarla çevrili bu şehirde tapınaklar, saraylar ve binlerce kil tabletin saklandığı arşivler bulunuyordu. Hititler, pek çok farklı halkın tanrılarını benimsedikleri için "bin tanrılı halk" olarak da anılır. Arşivlerdeki bu tabletler sayesinde onların yasalarını, inançlarını ve günlük yaşamlarını bugün bile öğrenebiliyoruz.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Hititlerin başkenti Hattuşa bugün hangi ilimizin sınırları içindedir?', 'Çorum', 'İzmir', 'Konya', 'Adıyaman', 'a', 'Metinde Hattuşa''nın Çorum''a bağlı Boğazkale yakınlarında olduğu yazıyor.' FROM texts WHERE slug = 'hititler-ve-kades-antlasmasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kadeş Savaşı hangi iki devlet arasında yapılmıştır?', 'Hititler ve Roma', 'Mısır ve Yunanistan', 'Selçuklular ve Mısır', 'Hititler ve Mısır', 'd', 'Metinde savaşın Hititler ile Mısırlılar arasında yapıldığı anlatılıyor.' FROM texts WHERE slug = 'hititler-ve-kades-antlasmasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kadeş Antlaşması''nı hangi hükümdarlar imzalamıştır?', 'I. Antiokhos ve II. Ramses', 'III. Hattuşili ve II. Ramses', 'Alaaddin Keykubad ve III. Hattuşili', 'Zeus ve Ramses', 'b', 'Metinde antlaşmayı III. Hattuşili ile II. Ramses''in imzaladığı yazıyor.' FROM texts WHERE slug = 'hititler-ve-kades-antlasmasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Antlaşmanın Hattuşa''da bulunan kil tableti bugün nerede sergilenmektedir?', 'Kahire''deki bir sarayda', 'İstanbul Arkeoloji Müzeleri''nde', 'New York''taki bir okulda', 'Hattuşa''daki surlarda', 'b', 'Metne göre tablet İstanbul Arkeoloji Müzeleri''nde sergilenmektedir.' FROM texts WHERE slug = 'hititler-ve-kades-antlasmasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kadeş Antlaşması''nın günümüze verdiği en önemli mesaj nedir?', 'Savaş arabaları en güçlü silahtır.', 'Her savaşın mutlaka bir kazananı vardır.', 'Kil tabletler kâğıttan daha değerlidir.', 'Anlaşmazlıklar savaş yerine konuşarak çözülebilir.', 'd', 'Metnin son cümlesi bu mesajı açıkça vurguluyor.' FROM texts WHERE slug = 'hititler-ve-kades-antlasmasi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('galapagos-adalari-ve-darwin', 'Galapagos Adaları ve Darwin', 'Güney Amerika kıyılarından yaklaşık bin kilometre açıkta, Büyük Okyanus''un ortasında bir grup volkanik ada bulunur: Galapagos Adaları. Ekvador''a ait olan bu adalar, milyonlarca yıl boyunca denizin altındaki yanardağların püskürmesiyle oluşmuştur. Anakaradan çok uzakta oldukları için adalarda, dünyanın başka hiçbir yerinde görülmeyen pek çok canlı yaşar.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Galapagos Adaları nasıl oluşmuştur?', 'Denizin altındaki yanardağların püskürmesiyle', 'Buzulların erimesiyle', 'Kum tepelerinin birikmesiyle', 'Anakaradan kopan parçalarla', 'a', 'Metinde adaların denizaltı yanardağlarının püskürmesiyle oluştuğu yazıyor.' FROM texts WHERE slug = 'galapagos-adalari-ve-darwin';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Darwin adalara hangi gemiyle gelmiştir?', 'Titanik', 'Ertuğrul', 'Beagle', 'Santa Maria', 'c', 'Metinde Darwin''in Beagle adlı gemiyle geldiği yazıyor.' FROM texts WHERE slug = 'galapagos-adalari-ve-darwin';
